import { performance } from "node:perf_hooks";

import { ObservationWriter } from "../metering/observations.mjs";

const VERSION = "0.3.3-m8";
const SETTLEMENT_WAITS = new AsyncLocalStorage();
const SEGMENTS = ["m1", "m2", "m3", "m4", "m5", "m6", "m8"];
