import { allow, ephemeral, v } from '@expo/snapback-codegen/define';

// Typing presence is ephemeral state (brief M3): it never touches the durable
// tables and expires on its own lease. Connection/session authority owns
// presence identity; the authored payload is display copy only.
//
// The brief pins "appears within 2 s of typing, expires within 5 s of the last
// keystroke", so the lease is deliberately short: a 3 s TTL with an 8 s ceiling
// keeps a stalled publisher inside the 5 s expiry window.
export const typing = ephemeral.collection({
  scope: { conversationId: v.id('conversations') },
  routing: ['conversationId'],
  key: 'connection',
  ttlMs: 3_000,
  maxTtlMs: 8_000,
  maxValueBytes: 128,
  publishRate: { sustainedHz: 8, burst: 16 },
  delivery: { mode: 'latest', dispatchMs: 40 },
  value: v.object({ displayName: v.string() }),
  publish: allow.all(),
  subscribe: allow.all(),
});
EOF
