cat > snapback/functions.mjs <<'MJSEOF'
import {
  defineAssetUpload,
  defineJsLiveQuery,
  defineJsMutation,
  results,
  v,
} from '@expo/snapback-codegen/define';

// ---------------------------------------------------------------------------
// Shared same-file helpers. Inline handlers capture no imports and no top-level
// const bindings, but statically reachable function declarations in this file
// are spliced in with the handler, so every helper below is a plain
// `function` declaration.
// ---------------------------------------------------------------------------

const MAX_ROWS = 1024;

/** The caller's profile row, resolved from the server-derived principal. */
async function callerProfile(ctx) {
  return await ctx.db
    .query('profiles')
    .withIndex('by_owner')
    .eq('ownerId', ctx.auth.userId)
    .first();
}

async function requireCallerProfile(ctx) {
  const profile = await callerProfile(ctx);
  if (!profile) ctx.refuse('PROFILE_REQUIRED', {});
  return profile;
}

function normalizeHandle(value) {
  return String(value ?? '').trim().toLowerCase();
}

function validHandle(handle) {
  return /^[a-z0-9_]{3,20}$/u.test(handle);
}

function bounded(value, max) {
  const text = String(value ?? '');
  return text.length <= max;
}

function pairKeyFor(a, b) {
  return a < b ? `${a}|${b}` : `${b}|${a}`;
}

/** Strictly increasing app-owned feed ordering key (no ties, total order). */
async function nextFeedSort(ctx) {
  const latest = await ctx.db
    .query('feedEntries')
    .withIndex('by_sort')
    .order('sortAt', 'desc')
    .take(1)
    .collect();
  const now = ctx.runtime.now();
  const previous = latest.length > 0 ? latest[0].sortAt : 0;
  return now > previous ? now : previous + 1;
}

async function profilesByIds(ctx, ids) {
  const unique = [];
  const seen = {};
  for (const id of ids) {
    if (id && !seen[id]) {
      seen[id] = true;
      unique.push(id);
    }
  }
  const map = {};
  for (let index = 0; index < unique.length; index += 256) {
    const rows = await ctx.db.getMany('profiles', unique.slice(index, index + 256));
    for (const row of rows) if (row) map[row._id] = row;
  }
  return map;
}

function profileCard(profile) {
  if (!profile) {
    return {
      profileId: '',
      displayName: 'Unknown',
      handle: 'unknown',
      avatarAssetId: null,
    };
  }
  return {
    profileId: profile._id,
    displayName: profile.displayName,
    handle: profile.handle,
    avatarAssetId: typeof profile.avatar === 'string' ? profile.avatar : null,
  };
}

async function mediaForPosts(ctx, postIds) {
  const byPost = {};
  for (const postId of postIds) {
    if (byPost[postId]) continue;
    const rows = await ctx.db
      .query('postMedia')
      .withIndex('by_post')
      .eq('postId', postId)
      .order('position', 'asc')
      .take(4)
      .collect();
    byPost[postId] = rows.map((row) => ({
      kind: row.kind,
      assetId: typeof row.image === 'string'
        ? row.image
        : (typeof row.video === 'string' ? row.video : ''),
    }));
  }
  return byPost;
}

async function viewerPostState(ctx, viewerProfileId, postIds) {
  const liked = {};
  const reposted = {};
  for (const postId of postIds) {
    if (liked[postId] !== undefined) continue;
    const like = await ctx.db
      .query('likes')
      .withIndex('by_post_actor')
      .eq('postId', postId)
      .eq('actorId', viewerProfileId)
      .first();
    liked[postId] = !!like;
    const repost = await ctx.db
      .query('reposts')
      .withIndex('by_post_actor')
      .eq('postId', postId)
      .eq('actorId', viewerProfileId)
      .first();
    reposted[postId] = !!repost;
  }
  return { liked, reposted };
}

async function followeeIds(ctx, profileId) {
  const rows = await ctx.db
    .query('follows')
    .withIndex('by_follower')
    .eq('followerId', profileId)
    .take(MAX_ROWS)
    .collect();
  return rows.map((row) => row.followeeId);
}

async function membershipRow(ctx, conversationId, profileId) {
  return await ctx.db
    .query('memberships')
    .withIndex('by_conversation_profile')
    .eq('conversationId', conversationId)
    .eq('profileId', profileId)
    .first();
}

async function conversationMembers(ctx, conversationId) {
  return await ctx.db
    .query('memberships')
    .withIndex('by_conversation')
    .eq('conversationId', conversationId)
    .take(64)
    .collect();
}

function conversationTitleFor(conversation, members, profileMap, viewerProfileId) {
  if (conversation.kind === 'group') return conversation.title;
  const other = members.find((row) => row.profileId !== viewerProfileId);
  const profile = other ? profileMap[other.profileId] : null;
  return profile ? profile.displayName : conversation.title;
}

/**
 * Aggregate receipt state for one of the viewer's own messages.
 * `sent` once the backend accepted it, `delivered` once every member of the
 * recipient set at send time has fetched past it, `read` once every one of
 * them has opened the conversation past it. Members who left have no row and
 * therefore drop out of the requirement.
 */
function aggregateReceipt(message, members) {
  const recipients = members.filter(
    (row) => row.profileId !== message.senderId && row.joinedSeq < message.seq,
  );
  if (recipients.length === 0) return 'sent';
  let delivered = true;
  let read = true;
  for (const row of recipients) {
    if (row.deliveredSeq < message.seq) delivered = false;
    if (row.readSeq < message.seq) read = false;
  }
  if (read) return 'read';
  if (delivered) return 'delivered';
  return 'sent';
}

