export const profileByHandle = defineJsLiveQuery({
  args: { handle: v.string() },
  auth: 'authenticated',
  reads: ['profiles', 'follows'],
  authScopeField: 'viewerId',
  result: results.records(PROFILE_RECORD),
  handler: async (ctx, args) => {
    const handle = String(args.handle ?? '').trim().toLowerCase();
    const profile = await ctx.db
      .query('profiles')
      .withIndex('by_handle')
      .eq('handle', handle)
      .first();
    if (!profile) return [];
    const viewer = await callerProfile(ctx);
    let viewerFollows = false;
    if (viewer && viewer._id !== profile._id) {
      const edge = await ctx.db
        .query('follows')
        .withIndex('by_pair')
        .eq('followerId', viewer._id)
        .eq('followeeId', profile._id)
        .first();
      viewerFollows = !!edge;
    }
    return [{
      viewerId: ctx.auth.userId,
      profileId: profile._id,
      displayName: profile.displayName,
      handle: profile.handle,
      bio: profile.bio,
      location: profile.location,
      link: profile.link,
      avatarAssetId: typeof profile.avatar === 'string' ? profile.avatar : null,
      followerCount: profile.followerCount,
      followingCount: profile.followingCount,
      isSelf: !!viewer && viewer._id === profile._id,
      viewerFollows,
    }];
  },
});

export const peopleSearch = defineJsLiveQuery({
  args: { query: v.string() },
  auth: 'authenticated',
  reads: ['profiles'],
  authScopeField: 'viewerId',
  result: results.records(v.object({
    viewerId: v.string(),
    profileId: v.string(),
    displayName: v.string(),
    handle: v.string(),
    avatarAssetId: v.union([v.string(), v.null()]),
    isSelf: v.boolean(),
  })),
  handler: async (ctx, args) => {
    const viewer = await callerProfile(ctx);
    const rows = await ctx.db
      .query('profiles')
      .withIndex('by_created')
      .order('createdAt', 'asc')
      .take(MAX_ROWS)
      .collect();
    // Case-insensitive word-prefix matching over NFC-normalized text.
    const needle = String(args.query ?? '').normalize('NFC').toLowerCase().trim();
    const matched = needle.length === 0
      ? rows
      : rows.filter((row) => {
        const words = `${row.displayName} ${row.handle}`
          .normalize('NFC')
          .toLowerCase()
          .split(/[^\p{L}\p{N}_]+/u)
          .filter(Boolean);
        return words.some((word) => word.startsWith(needle));
      });
    return matched.slice(0, 50).map((row) => ({
      viewerId: ctx.auth.userId,
      profileId: row._id,
      displayName: row.displayName,
      handle: row.handle,
      avatarAssetId: typeof row.avatar === 'string' ? row.avatar : null,
      isSelf: !!viewer && viewer._id === row._id,
    }));
  },
});

export const createProfile = defineJsMutation({
  args: {
    displayName: v.string(),
    handle: v.string(),
    bio: v.string(),
    location: v.string(),
    link: v.string(),
  },
  auth: 'authenticated',
  writes: ['profiles'],
  refusals: ['PROFILE_EXISTS', 'HANDLE_TAKEN', 'HANDLE_INVALID', 'FIELD_TOO_LONG'],
  trackedRefusals: ['HANDLE_TAKEN'],
  result: results.value(v.id('profiles')),
  handler: async (ctx, args) => {
    const existing = await callerProfile(ctx);
    if (existing) ctx.refuse('PROFILE_EXISTS', {});
    const handle = normalizeHandle(args.handle);
    if (!validHandle(handle)) ctx.refuse('HANDLE_INVALID', { handle });
    const displayName = String(args.displayName ?? '').trim();
    if (displayName.length < 1 || displayName.length > 50) {
      ctx.refuse('FIELD_TOO_LONG', { field: 'displayName' });
    }
    if (!bounded(args.bio, 200)) ctx.refuse('FIELD_TOO_LONG', { field: 'bio' });
    if (!bounded(args.location, 50)) ctx.refuse('FIELD_TOO_LONG', { field: 'location' });
    const taken = await ctx.db
      .query('profiles')
      .withIndex('by_handle')
      .eq('handle', handle)
      .first();
    if (taken) ctx.refuse('HANDLE_TAKEN', { handle });
    return await ctx.db.insert('profiles', {
      ownerId: ctx.auth.userId,
      displayName,
      handle,
      bio: String(args.bio ?? ''),
      location: String(args.location ?? ''),
      link: String(args.link ?? ''),
      followerCount: 0,
      followingCount: 0,
      createdAt: ctx.runtime.now(),
    });
  },
});

