const FEED_RECORD = v.object({
  viewerId: v.string(),
  entryId: v.string(),
  entryKind: v.string(),
  sortAt: v.integer(),
  repostedByName: v.union([v.string(), v.null()]),
  postId: v.string(),
  text: v.string(),
  postKind: v.string(),
  createdAt: v.integer(),
  authorProfileId: v.string(),
  authorName: v.string(),
  authorHandle: v.string(),
  authorAvatarAssetId: v.union([v.string(), v.null()]),
  imageAssetIds: v.array(v.string()),
  videoAssetId: v.union([v.string(), v.null()]),
  likeCount: v.integer(),
  repostCount: v.integer(),
  replyCount: v.integer(),
  viewerLiked: v.boolean(),
  viewerReposted: v.boolean(),
});

async function decorateEntries(ctx, viewer, entries) {
  const postIds = entries.map((entry) => entry.postId);
  const postMap = {};
  for (let index = 0; index < postIds.length; index += 256) {
    const rows = await ctx.db.getMany('posts', postIds.slice(index, index + 256));
    for (const row of rows) if (row) postMap[row._id] = row;
  }
  const actorIds = entries.map((entry) => entry.actorId);
  const authorIds = Object.keys(postMap).map((key) => postMap[key].authorId);
  const profileMap = await profilesByIds(ctx, actorIds.concat(authorIds));
  const mediaMap = await mediaForPosts(ctx, postIds);
  const viewerState = await viewerPostState(ctx, viewer._id, postIds);
  const out = [];
  for (const entry of entries) {
    const post = postMap[entry.postId];
    if (!post) continue;
    const author = profileMap[post.authorId];
    const authorCard = profileCard(author);
    const media = mediaMap[entry.postId] ?? [];
    const reposter = entry.kind === 'repost' ? profileMap[entry.actorId] : null;
    out.push({
      viewerId: ctx.auth.userId,
      entryId: entry._id,
      entryKind: entry.kind,
      sortAt: entry.sortAt,
      repostedByName: reposter ? reposter.displayName : null,
      postId: post._id,
      text: post.text,
      postKind: post.kind,
      createdAt: post.createdAt,
      authorProfileId: authorCard.profileId,
      authorName: authorCard.displayName,
      authorHandle: authorCard.handle,
      authorAvatarAssetId: authorCard.avatarAssetId,
      imageAssetIds: media.filter((item) => item.kind === 'image').map((item) => item.assetId),
      videoAssetId: media.find((item) => item.kind === 'video')?.assetId ?? null,
      likeCount: post.likeCount,
      repostCount: post.repostCount,
      replyCount: post.replyCount,
      viewerLiked: viewerState.liked[post._id] === true,
      viewerReposted: viewerState.reposted[post._id] === true,
    });
  }
  return out;
}

/**
 * One keyset page of a feed. `beforeSortAt` is the inclusive cursor captured
 * from the last rendered entry of the previous page; the client de-duplicates
 * by `entryId`, so a concurrent insert can never open a gap between pages.
 */
export const feedPage = defineJsLiveQuery({
  args: {
    scope: v.string(),
    limit: v.integer(),
    beforeSortAt: v.optional(v.integer()),
  },
  auth: 'authenticated',
  reads: ['feedEntries', 'posts', 'profiles', 'follows', 'likes', 'reposts', 'postMedia'],
  authScopeField: 'viewerId',
  result: results.records(FEED_RECORD),
  handler: async (ctx, args) => {
    const viewer = await callerProfile(ctx);
    if (!viewer) return [];
    const limit = Math.max(1, Math.min(100, Number(args.limit) || 20));
    const cursor = typeof args.beforeSortAt === 'number' ? args.beforeSortAt : null;

    let entries = [];
    if (args.scope === 'following') {
      // Implicit self-follow: the viewer's own originals and reposts are always
      // in Following, without a persisted self-edge.
      const actorIds = [viewer._id].concat(await followeeIds(ctx, viewer._id));
      for (const actorId of actorIds) {
        let builder = ctx.db
          .query('feedEntries')
          .withIndex('by_actor_sort')
          .eq('actorId', actorId);
        if (cursor !== null) builder = builder.lte('sortAt', cursor);
        const rows = await builder.order('sortAt', 'desc').take(limit).collect();
        for (const row of rows) entries.push(row);
      }
      entries.sort((left, right) => right.sortAt - left.sortAt);
      entries = entries.slice(0, limit);
    } else {
      let builder = ctx.db.query('feedEntries').withIndex('by_sort');
      if (cursor !== null) builder = builder.lte('sortAt', cursor);
      entries = await builder.order('sortAt', 'desc').take(limit).collect();
    }
    return await decorateEntries(ctx, viewer, entries);
  },
});

export const authorPosts = defineJsLiveQuery({
  args: { handle: v.string(), limit: v.integer() },
  auth: 'authenticated',
  reads: ['feedEntries', 'posts', 'profiles', 'likes', 'reposts', 'postMedia'],
  authScopeField: 'viewerId',
  result: results.records(FEED_RECORD),
  handler: async (ctx, args) => {
    const viewer = await callerProfile(ctx);
    if (!viewer) return [];
    const handle = String(args.handle ?? '').trim().toLowerCase();
    const author = await ctx.db
      .query('profiles')
      .withIndex('by_handle')
      .eq('handle', handle)
      .first();
    if (!author) return [];
    const posts = await ctx.db
      .query('posts')
      .withIndex('by_author_created')
      .eq('authorId', author._id)
      .order('createdAt', 'desc')
      .take(Math.max(1, Math.min(100, Number(args.limit) || 20)))
      .collect();
    const originals = posts.filter((post) => !post.parentId);
    const entries = originals.map((post) => ({
      _id: `author:${post._id}`,
      actorId: author._id,
      postId: post._id,
      kind: 'post',
      sortAt: post.createdAt,
    }));
    return await decorateEntries(ctx, viewer, entries);
  },
});

export const thread = defineJsLiveQuery({
  args: { postId: v.id('posts') },
  auth: 'authenticated',
  reads: ['posts', 'profiles', 'likes', 'reposts', 'postMedia'],
  authScopeField: 'viewerId',
  result: results.records(FEED_RECORD),
  handler: async (ctx, args) => {
    const viewer = await callerProfile(ctx);
    if (!viewer) return [];
    const parent = await ctx.db.get('posts', args.postId);
    if (!parent) return [];
    const replies = await ctx.db
      .query('posts')
      .withIndex('by_parent_created')
      .eq('parentId', parent._id)
      .order('createdAt', 'asc')
      .take(200)
      .collect();
    const entries = [parent].concat(replies).map((post) => ({
      _id: `thread:${post._id}`,
      actorId: post.authorId,
      postId: post._id,
      kind: 'post',
      sortAt: post.createdAt,
    }));
    return await decorateEntries(ctx, viewer, entries);
  },
});

export const createPost = defineJsMutation({
  args: {
    text: v.string(),
    kind: v.string(),
    parentId: v.optional(v.id('posts')),
    imageAssetIds: v.optional(v.array(v.string())),
    videoAssetId: v.optional(v.string()),
  },
  auth: 'authenticated',
  writes: ['posts', 'postMedia', 'feedEntries'],
  refusals: ['PROFILE_REQUIRED', 'TEXT_TOO_LONG', 'MEDIA_INVALID', 'PARENT_MISSING'],
  result: results.value(v.id('posts')),
  handler: async (ctx, args) => {
    const author = await requireCallerProfile(ctx);
    const text = String(args.text ?? '');
    if (text.length > 500) ctx.refuse('TEXT_TOO_LONG', { limit: 500 });
    const images = Array.isArray(args.imageAssetIds) ? args.imageAssetIds : [];
    const video = typeof args.videoAssetId === 'string' && args.videoAssetId.length > 0
      ? args.videoAssetId
      : null;
    if (images.length > 0 && video) ctx.refuse('MEDIA_INVALID', { reason: 'mixed' });
    if (images.length > 4) ctx.refuse('MEDIA_INVALID', { reason: 'too-many-images' });
    let kind = 'text';
    if (video) kind = 'video';
    else if (images.length > 0) kind = 'images';
    if (kind === 'text' && text.trim().length === 0) {
      ctx.refuse('MEDIA_INVALID', { reason: 'empty' });
    }

    let parent = null;
    if (args.parentId) {
      parent = await ctx.db.get('posts', args.parentId);
      if (!parent) ctx.refuse('PARENT_MISSING', {});
    }

    const now = ctx.runtime.now();
    const postId = await ctx.db.insert('posts', {
      authorId: author._id,
      text,
      kind,
      ...(parent ? { parentId: parent._id } : {}),
      likeCount: 0,
      repostCount: 0,
      replyCount: 0,
      createdAt: now,
    });

    let position = 0;
    for (const assetId of images) {
      await ctx.db.insert('postMedia', {
        postId,
        position,
        kind: 'image',
        image: await ctx.assets.attach(assetId, { upload: 'postImageUpload' }),
      });
      position += 1;
    }
    if (video) {
      await ctx.db.insert('postMedia', {
        postId,
        position: 0,
        kind: 'video',
        video: await ctx.assets.attach(video, { upload: 'postVideoUpload' }),
      });
    }

    if (parent) {
      // Replies never enter either feed: no feed entry is projected.
      await ctx.db.patch('posts', parent._id, { replyCount: parent.replyCount + 1 });
    } else {
      await ctx.db.insert('feedEntries', {
        actorId: author._id,
        postId,
        kind: 'post',
        sortAt: await nextFeedSort(ctx),
      });
    }
    return postId;
  },
});

export const setFollow = defineJsMutation({
  args: {
    targetProfileId: v.id('profiles'),
    following: v.boolean(),
    mutationId: v.string(),
  },
  auth: 'authenticated',
  writes: ['follows', 'profiles'],
  refusals: ['PROFILE_REQUIRED', 'SELF_FOLLOW', 'TARGET_MISSING'],
  result: results.value(v.boolean()),
  handler: async (ctx, args) => {
    const viewer = await requireCallerProfile(ctx);
    if (viewer._id === args.targetProfileId) ctx.refuse('SELF_FOLLOW', {});
    const target = await ctx.db.get('profiles', args.targetProfileId);
    if (!target) ctx.refuse('TARGET_MISSING', {});
    const existing = await ctx.db
      .query('follows')
      .withIndex('by_pair')
      .eq('followerId', viewer._id)
      .eq('followeeId', target._id)
      .first();
    // Idempotent set-state intent: `set` ensures the edge, `clear` ensures its
    // absence. Never a flip, so at-least-once retry cannot invert it.
    if (args.following && !existing) {
      await ctx.db.insert('follows', {
        followerId: viewer._id,
        followeeId: target._id,
        createdAt: ctx.runtime.now(),
      });
      await ctx.db.patch('profiles', viewer._id, { followingCount: viewer.followingCount + 1 });
      await ctx.db.patch('profiles', target._id, { followerCount: target.followerCount + 1 });
    } else if (!args.following && existing) {
      await ctx.db.delete('follows', existing._id);
      await ctx.db.patch('profiles', viewer._id, {
        followingCount: Math.max(0, viewer.followingCount - 1),
      });
      await ctx.db.patch('profiles', target._id, {
        followerCount: Math.max(0, target.followerCount - 1),
      });
    }
    return args.following === true;
  },
});

export const setLike = defineJsMutation({
  args: { postId: v.id('posts'), liked: v.boolean(), mutationId: v.string() },
  auth: 'authenticated',
  writes: ['likes', 'posts'],
  refusals: ['PROFILE_REQUIRED', 'POST_MISSING'],
  result: results.value(v.boolean()),
  handler: async (ctx, args) => {
    const viewer = await requireCallerProfile(ctx);
    const post = await ctx.db.get('posts', args.postId);
    if (!post) ctx.refuse('POST_MISSING', {});
    const existing = await ctx.db
      .query('likes')
      .withIndex('by_post_actor')
      .eq('postId', post._id)
      .eq('actorId', viewer._id)
      .first();
    if (args.liked && !existing) {
      await ctx.db.insert('likes', {
        postId: post._id,
        actorId: viewer._id,
        createdAt: ctx.runtime.now(),
      });
      await ctx.db.patch('posts', post._id, { likeCount: post.likeCount + 1 });
    } else if (!args.liked && existing) {
      await ctx.db.delete('likes', existing._id);
      await ctx.db.patch('posts', post._id, { likeCount: Math.max(0, post.likeCount - 1) });
    }
    return args.liked === true;
  },
});

export const setRepost = defineJsMutation({
  args: { postId: v.id('posts'), reposted: v.boolean(), mutationId: v.string() },
  auth: 'authenticated',
  writes: ['reposts', 'posts', 'feedEntries'],
  refusals: ['PROFILE_REQUIRED', 'POST_MISSING', 'REPLY_NOT_REPOSTABLE'],
  result: results.value(v.boolean()),
  handler: async (ctx, args) => {
    const viewer = await requireCallerProfile(ctx);
    const post = await ctx.db.get('posts', args.postId);
    if (!post) ctx.refuse('POST_MISSING', {});
    const existing = await ctx.db
      .query('reposts')
      .withIndex('by_post_actor')
      .eq('postId', post._id)
      .eq('actorId', viewer._id)
      .first();
    if (args.reposted && !existing) {
      await ctx.db.insert('reposts', {
        postId: post._id,
        actorId: viewer._id,
        createdAt: ctx.runtime.now(),
      });
      await ctx.db.patch('posts', post._id, { repostCount: post.repostCount + 1 });
      await ctx.db.insert('feedEntries', {
        actorId: viewer._id,
        postId: post._id,
        kind: 'repost',
        sortAt: await nextFeedSort(ctx),
      });
    } else if (!args.reposted && existing) {
      await ctx.db.delete('reposts', existing._id);
      await ctx.db.patch('posts', post._id, { repostCount: Math.max(0, post.repostCount - 1) });
      const entry = await ctx.db
        .query('feedEntries')
        .withIndex('by_actor_post_kind')
        .eq('actorId', viewer._id)
        .eq('postId', post._id)
        .eq('kind', 'repost')
        .first();
      if (entry) await ctx.db.delete('feedEntries', entry._id);
    }
    return args.reposted === true;
  },
});

