export const myChats = defineJsLiveQuery({
  args: {},
  auth: 'authenticated',
  reads: ['memberships', 'conversations', 'profiles', 'messages'],
  authScopeField: 'viewerId',
  result: results.records(v.object({
    viewerId: v.string(),
    conversationId: v.string(),
    kind: v.string(),
    title: v.string(),
    preview: v.string(),
    avatarAssetId: v.union([v.string(), v.null()]),
    unreadCount: v.integer(),
    updatedAt: v.integer(),
  })),
  handler: async (ctx) => {
    const viewer = await callerProfile(ctx);
    if (!viewer) return [];
    const mine = await ctx.db
      .query('memberships')
      .withIndex('by_profile')
      .eq('profileId', viewer._id)
      .take(500)
      .collect();
    const rows = [];
    for (const membership of mine) {
      const conversation = await ctx.db.get('conversations', membership.conversationId);
      if (!conversation) continue;
      const members = await conversationMembers(ctx, conversation._id);
      const profileMap = await profilesByIds(ctx, members.map((row) => row.profileId));
      const other = members.find((row) => row.profileId !== viewer._id);
      const otherProfile = other ? profileMap[other.profileId] : null;
      rows.push({
        viewerId: ctx.auth.userId,
        conversationId: conversation._id,
        kind: conversation.kind,
        title: conversationTitleFor(conversation, members, profileMap, viewer._id),
        preview: conversation.lastPreview,
        avatarAssetId: conversation.kind === 'dm' && otherProfile
          && typeof otherProfile.avatar === 'string'
          ? otherProfile.avatar
          : null,
        unreadCount: Math.max(0, conversation.messageCount - membership.readSeq),
        updatedAt: conversation.updatedAt,
      });
    }
    rows.sort((left, right) => right.updatedAt - left.updatedAt);
    return rows;
  },
});

export const chatDetails = defineJsLiveQuery({
  args: { conversationId: v.id('conversations') },
  auth: 'authenticated',
  reads: ['conversations', 'memberships', 'profiles'],
  authScopeField: 'viewerId',
  result: results.records(v.object({
    viewerId: v.string(),
    conversationId: v.string(),
    kind: v.string(),
    title: v.string(),
    description: v.string(),
    viewerIsMember: v.boolean(),
    viewerIsAdmin: v.boolean(),
    viewerProfileId: v.string(),
    messageCount: v.integer(),
    members: v.array(v.object({
      profileId: v.string(),
      displayName: v.string(),
      handle: v.string(),
      role: v.string(),
      avatarAssetId: v.union([v.string(), v.null()]),
    })),
  })),
  handler: async (ctx, args) => {
    const viewer = await callerProfile(ctx);
    if (!viewer) return [];
    const conversation = await ctx.db.get('conversations', args.conversationId);
    if (!conversation) return [];
    const members = await conversationMembers(ctx, conversation._id);
    const mine = members.find((row) => row.profileId === viewer._id);
    // Read scoping is the app's own gate: a non-member gets nothing back.
    if (!mine) return [];
    const profileMap = await profilesByIds(ctx, members.map((row) => row.profileId));
    return [{
      viewerId: ctx.auth.userId,
      conversationId: conversation._id,
      kind: conversation.kind,
      title: conversationTitleFor(conversation, members, profileMap, viewer._id),
      description: conversation.description,
      viewerIsMember: true,
      viewerIsAdmin: mine.role === 'admin',
      viewerProfileId: viewer._id,
      messageCount: conversation.messageCount,
      members: members.map((row) => {
        const card = profileCard(profileMap[row.profileId]);
        return {
          profileId: row.profileId,
          displayName: card.displayName,
          handle: card.handle,
          role: row.role,
          avatarAssetId: card.avatarAssetId,
        };
      }),
    }];
  },
});

export const chatMessages = defineJsLiveQuery({
  args: { conversationId: v.id('conversations'), limit: v.integer() },
  auth: 'authenticated',
  reads: ['messages', 'memberships', 'profiles', 'conversations'],
  authScopeField: 'viewerId',
  result: results.records(v.object({
    viewerId: v.string(),
    messageId: v.string(),
    conversationId: v.string(),
    seq: v.integer(),
    senderProfileId: v.string(),
    senderName: v.string(),
    senderAvatarAssetId: v.union([v.string(), v.null()]),
    isMine: v.boolean(),
    text: v.string(),
    kind: v.string(),
    sentAt: v.integer(),
    quoteMessageId: v.union([v.string(), v.null()]),
    quoteSenderName: v.union([v.string(), v.null()]),
    quoteExcerpt: v.union([v.string(), v.null()]),
    receipt: v.string(),
  })),
  handler: async (ctx, args) => {
    const viewer = await callerProfile(ctx);
    if (!viewer) return [];
    const mine = await membershipRow(ctx, args.conversationId, viewer._id);
    // Membership is the read boundary for message history.
    if (!mine) return [];
    const members = await conversationMembers(ctx, args.conversationId);
    const limit = Math.max(1, Math.min(500, Number(args.limit) || 200));
    const recent = await ctx.db
      .query('messages')
      .withIndex('by_conversation_seq')
      .eq('conversationId', args.conversationId)
      .order('seq', 'desc')
      .take(limit)
      .collect();
    const ordered = recent.slice().sort((left, right) => left.seq - right.seq);
    const profileMap = await profilesByIds(ctx, ordered.map((row) => row.senderId));
    const byId = {};
    for (const row of ordered) byId[row._id] = row;
    const out = [];
    for (const message of ordered) {
      const sender = profileCard(profileMap[message.senderId]);
      let quote = null;
      if (message.quoteId) {
        quote = byId[message.quoteId] ?? await ctx.db.get('messages', message.quoteId);
      }
      const quoteSender = quote ? profileMap[quote.senderId] : null;
      out.push({
        viewerId: ctx.auth.userId,
        messageId: message._id,
        conversationId: message.conversationId,
        seq: message.seq,
        senderProfileId: message.senderId,
        senderName: sender.displayName,
        senderAvatarAssetId: sender.avatarAssetId,
        isMine: message.senderId === viewer._id,
        text: message.text,
        kind: message.kind,
        sentAt: message.sentAt,
        quoteMessageId: quote ? quote._id : null,
        quoteSenderName: quoteSender ? quoteSender.displayName : (quote ? 'Unknown' : null),
        quoteExcerpt: quote ? quote.text : null,
        receipt: message.senderId === viewer._id
          ? aggregateReceipt(message, members)
          : 'none',
      });
    }
    return out;
  },
});

export const createDm = defineJsMutation({
  args: { otherProfileId: v.id('profiles') },
  auth: 'authenticated',
  writes: ['conversations', 'memberships'],
  refusals: ['PROFILE_REQUIRED', 'TARGET_MISSING', 'SELF_DM'],
  result: results.value(v.id('conversations')),
  handler: async (ctx, args) => {
    const viewer = await requireCallerProfile(ctx);
    if (viewer._id === args.otherProfileId) ctx.refuse('SELF_DM', {});
    const other = await ctx.db.get('profiles', args.otherProfileId);
    if (!other) ctx.refuse('TARGET_MISSING', {});
    const pairKey = pairKeyFor(viewer._id, other._id);
    // At most one DM channel per pair: starting the "same" DM again resolves
    // to the existing channel instead of creating a duplicate.
    const existing = await ctx.db
      .query('conversations')
      .withIndex('by_pair')
      .eq('pairKey', pairKey)
      .first();
    if (existing) return existing._id;
    const now = ctx.runtime.now();
    const conversationId = await ctx.db.insert('conversations', {
      kind: 'dm',
      title: other.displayName,
      description: '',
      createdBy: viewer._id,
      pairKey,
      messageCount: 0,
      lastPreview: '',
      updatedAt: now,
      createdAt: now,
    });
    for (const profileId of [viewer._id, other._id]) {
      await ctx.db.insert('memberships', {
        conversationId,
        profileId,
        role: 'member',
        joinedSeq: 0,
        deliveredSeq: 0,
        readSeq: 0,
        joinedAt: now,
      });
    }
    return conversationId;
  },
});

export const createGroup = defineJsMutation({
  args: {
    title: v.string(),
    description: v.string(),
    memberProfileIds: v.array(v.id('profiles')),
  },
  auth: 'authenticated',
  writes: ['conversations', 'memberships'],
  refusals: ['PROFILE_REQUIRED', 'TITLE_INVALID', 'MEMBER_COUNT_INVALID'],
  result: results.value(v.id('conversations')),
  handler: async (ctx, args) => {
    const viewer = await requireCallerProfile(ctx);
    const title = String(args.title ?? '').trim();
    if (title.length < 1 || title.length > 50) ctx.refuse('TITLE_INVALID', {});
    if (!bounded(args.description, 200)) ctx.refuse('TITLE_INVALID', { field: 'description' });
    const others = [];
    for (const id of args.memberProfileIds) {
      if (id !== viewer._id && !others.includes(id)) others.push(id);
    }
    const total = others.length + 1;
    if (total < 2 || total > 50) ctx.refuse('MEMBER_COUNT_INVALID', { total });
    const now = ctx.runtime.now();
    // Two groups with identical membership are distinct entities: no dedupe.
    const conversationId = await ctx.db.insert('conversations', {
      kind: 'group',
      title,
      description: String(args.description ?? ''),
      createdBy: viewer._id,
      messageCount: 0,
      lastPreview: '',
      updatedAt: now,
      createdAt: now,
    });
    await ctx.db.insert('memberships', {
      conversationId,
      profileId: viewer._id,
      role: 'admin',
      joinedSeq: 0,
      deliveredSeq: 0,
      readSeq: 0,
      joinedAt: now,
    });
    for (const profileId of others) {
      const profile = await ctx.db.get('profiles', profileId);
      if (!profile) continue;
      await ctx.db.insert('memberships', {
        conversationId,
        profileId,
        role: 'member',
        joinedSeq: 0,
        deliveredSeq: 0,
        readSeq: 0,
        joinedAt: now,
      });
    }
    return conversationId;
  },
});

export const addMember = defineJsMutation({
  args: { conversationId: v.id('conversations'), profileId: v.id('profiles') },
  auth: 'authenticated',
  writes: ['memberships', 'conversations'],
  refusals: ['PROFILE_REQUIRED', 'NOT_ADMIN', 'NOT_GROUP', 'TARGET_MISSING', 'MEMBER_COUNT_INVALID'],
  result: results.value(v.boolean()),
  handler: async (ctx, args) => {
    const viewer = await requireCallerProfile(ctx);
    const conversation = await ctx.db.get('conversations', args.conversationId);
    if (!conversation) ctx.refuse('TARGET_MISSING', {});
    if (conversation.kind !== 'group') ctx.refuse('NOT_GROUP', {});
    const mine = await membershipRow(ctx, conversation._id, viewer._id);
    if (!mine || mine.role !== 'admin') ctx.refuse('NOT_ADMIN', {});
    const target = await ctx.db.get('profiles', args.profileId);
    if (!target) ctx.refuse('TARGET_MISSING', {});
    const existing = await membershipRow(ctx, conversation._id, target._id);
    if (existing) return true;
    const members = await conversationMembers(ctx, conversation._id);
    if (members.length >= 50) ctx.refuse('MEMBER_COUNT_INVALID', { total: members.length + 1 });
    // Adds take effect immediately and the new member sees full prior history:
    // joinedSeq 0 keeps every earlier message readable.
    await ctx.db.insert('memberships', {
      conversationId: conversation._id,
      profileId: target._id,
      role: 'member',
      joinedSeq: 0,
      deliveredSeq: 0,
      readSeq: 0,
      joinedAt: ctx.runtime.now(),
    });
    return true;
  },
});

export const removeMember = defineJsMutation({
  args: { conversationId: v.id('conversations'), profileId: v.id('profiles') },
  auth: 'authenticated',
  writes: ['memberships'],
  refusals: ['PROFILE_REQUIRED', 'NOT_ADMIN', 'NOT_GROUP', 'TARGET_MISSING'],
  result: results.value(v.boolean()),
  handler: async (ctx, args) => {
    const viewer = await requireCallerProfile(ctx);
    const conversation = await ctx.db.get('conversations', args.conversationId);
    if (!conversation) ctx.refuse('TARGET_MISSING', {});
    if (conversation.kind !== 'group') ctx.refuse('NOT_GROUP', {});
    const mine = await membershipRow(ctx, conversation._id, viewer._id);
    // Only an admin may remove another member; anyone may remove themselves
    // (that is "leave").
    const removingSelf = args.profileId === viewer._id;
    if (!mine || (!removingSelf && mine.role !== 'admin')) ctx.refuse('NOT_ADMIN', {});
    const target = await membershipRow(ctx, conversation._id, args.profileId);
    if (!target) ctx.refuse('TARGET_MISSING', {});
    await ctx.db.delete('memberships', target._id);
    return true;
  },
});

export const promoteMember = defineJsMutation({
  args: { conversationId: v.id('conversations'), profileId: v.id('profiles') },
  auth: 'authenticated',
  writes: ['memberships'],
  refusals: ['PROFILE_REQUIRED', 'NOT_ADMIN', 'TARGET_MISSING'],
  result: results.value(v.boolean()),
  handler: async (ctx, args) => {
    const viewer = await requireCallerProfile(ctx);
    const mine = await membershipRow(ctx, args.conversationId, viewer._id);
    if (!mine || mine.role !== 'admin') ctx.refuse('NOT_ADMIN', {});
    const target = await membershipRow(ctx, args.conversationId, args.profileId);
    if (!target) ctx.refuse('TARGET_MISSING', {});
    await ctx.db.patch('memberships', target._id, { role: 'admin' });
    return true;
  },
});

export const sendMessage = defineJsMutation({
  args: {
    conversationId: v.id('conversations'),
    text: v.string(),
    quoteId: v.optional(v.id('messages')),
  },
  auth: 'authenticated',
  writes: ['messages', 'conversations', 'memberships'],
  refusals: ['PROFILE_REQUIRED', 'NOT_MEMBER', 'TEXT_TOO_LONG', 'QUOTE_INVALID'],
  result: results.value(v.id('messages')),
  handler: async (ctx, args) => {
    const viewer = await requireCallerProfile(ctx);
    const conversation = await ctx.db.get('conversations', args.conversationId);
    if (!conversation) ctx.refuse('NOT_MEMBER', {});
    const mine = await membershipRow(ctx, conversation._id, viewer._id);
    // Removed members immediately stop being able to write or receive.
    if (!mine) ctx.refuse('NOT_MEMBER', {});
    const text = String(args.text ?? '');
    if (text.length === 0 || text.length > 2000) ctx.refuse('TEXT_TOO_LONG', { limit: 2000 });
    if (args.quoteId) {
      const quoted = await ctx.db.get('messages', args.quoteId);
      if (!quoted || quoted.conversationId !== conversation._id) {
        ctx.refuse('QUOTE_INVALID', {});
      }
    }
    const members = await conversationMembers(ctx, conversation._id);
    const seq = conversation.messageCount + 1;
    const now = ctx.runtime.now();
    const messageId = await ctx.db.insert('messages', {
      conversationId: conversation._id,
      senderId: viewer._id,
      kind: 'text',
      text,
      ...(args.quoteId ? { quoteId: args.quoteId } : {}),
      seq,
      recipientCount: Math.max(0, members.length - 1),
      sentAt: now,
    });
    await ctx.db.patch('conversations', conversation._id, {
      messageCount: seq,
      lastPreview: text,
      lastSenderId: viewer._id,
      updatedAt: now,
    });
    // The sender has necessarily delivered and read their own message.
    await ctx.db.patch('memberships', mine._id, { deliveredSeq: seq, readSeq: seq });
    return messageId;
  },
});

export const markChatState = defineJsMutation({
  args: {
    conversationId: v.id('conversations'),
    deliveredSeq: v.integer(),
    readSeq: v.integer(),
  },
  auth: 'authenticated',
  writes: ['memberships'],
  refusals: ['PROFILE_REQUIRED', 'NOT_MEMBER'],
  result: results.value(v.boolean()),
  handler: async (ctx, args) => {
    const viewer = await requireCallerProfile(ctx);
    const mine = await membershipRow(ctx, args.conversationId, viewer._id);
    if (!mine) ctx.refuse('NOT_MEMBER', {});
    // Receipts are monotonic: a watermark never moves backwards.
    const deliveredSeq = Math.max(mine.deliveredSeq, Number(args.deliveredSeq) || 0);
    const readSeq = Math.max(mine.readSeq, Number(args.readSeq) || 0);
    if (deliveredSeq === mine.deliveredSeq && readSeq === mine.readSeq) return false;
    await ctx.db.patch('memberships', mine._id, {
      deliveredSeq: Math.max(deliveredSeq, readSeq),
      readSeq,
    });
    return true;
  },
});
