// ---------------------------------------------------------------------------
// Seed ledger. The fixture action logs are replayed through the ordinary auth
// and mutation paths above; this ledger records which server-owned entity each
// action-log id produced so a second run of the same segment is a no-op.
// ---------------------------------------------------------------------------

export const seedRefs = defineJsLiveQuery({
  args: {},
  auth: 'authenticated',
  reads: ['seedRefs'],
  result: results.records(v.object({
    logId: v.string(),
    kind: v.string(),
    entityId: v.string(),
  })),
  handler: async (ctx) => {
    const rows = await ctx.db
      .query('seedRefs')
      .withIndex('by_logid')
      .order('logId', 'asc')
      .take(1024)
      .collect();
    return rows.map((row) => ({
      logId: row.logId,
      kind: row.kind,
      entityId: row.entityId,
    }));
  },
});

export const recordSeedRef = defineJsMutation({
  args: { logId: v.string(), kind: v.string(), entityId: v.string() },
  auth: 'authenticated',
  writes: ['seedRefs'],
  refusals: ['PROFILE_REQUIRED'],
  result: results.value(v.string()),
  handler: async (ctx, args) => {
    await requireCallerProfile(ctx);
    const existing = await ctx.db
      .query('seedRefs')
      .withIndex('by_logid')
      .eq('logId', args.logId)
      .first();
    if (existing) return existing.entityId;
    await ctx.db.insert('seedRefs', {
      logId: String(args.logId),
      kind: String(args.kind),
      entityId: String(args.entityId),
      createdAt: ctx.runtime.now(),
    });
    return String(args.entityId);
  },
});
