#!/usr/bin/env node
// Fixture action-log replay adapter for Clique.
//
// The fixture pack's starter logs are backend-neutral action lines, not a
// database import. This adapter drives the application's *own* auth and
// mutation paths: every `register` runs the real password signup, every other
// verb is an ordinary authenticated mutation, and each action settles before
// the next one is submitted, so replay order is the authoritative order.
//
// Idempotency is per installed segment and lives in the app's `seedRefs`
// ledger: an action-log id that already names a server entity is skipped, and
// every set-state verb (follow/like/repost/react) is already a set/clear
// intent rather than a flip.

import { readFile } from 'node:fs/promises';
import { basename, resolve } from 'node:path';
import { SnapbackClient, createAssetClient } from '@expo/snapback-client';
import {
  AuthCoordinator,
  createMemoryAuthCustodyStorage,
} from '@expo/snapback-contract/auth-coordinator';

import api, { app } from '../snapback/generated/api.mjs';

export const FIXTURES = resolve(
  process.env.CLIQUE_FIXTURES
    ?? '/Users/ccheever/bench-matrix-20260823-r2/instrument/fixtures/social-messenger',
);

const CONTENT_TYPES = new Map([
  ['png', 'image/png'],
  ['jpg', 'image/jpeg'],
  ['jpeg', 'image/jpeg'],
  ['webp', 'image/webp'],
  ['mp4', 'video/mp4'],
]);

/** Split one action line into tokens, keeping JSON string literals intact. */
export function tokenize(line) {
  const tokens = [];
  let index = 0;
  while (index < line.length) {
    const char = line[index];
    if (char === ' ' || char === '\t') { index += 1; continue; }
    if (char === '"') {
      let end = index + 1;
      let escaped = false;
      while (end < line.length) {
        const current = line[end];
        if (escaped) escaped = false;
        else if (current === '\\') escaped = true;
        else if (current === '"') break;
        end += 1;
      }
      if (end >= line.length) throw new Error(`unterminated string in: ${line}`);
      tokens.push({ quoted: true, value: JSON.parse(line.slice(index, end + 1)) });
      index = end + 1;
      continue;
    }
    let end = index;
    while (end < line.length && line[end] !== ' ' && line[end] !== '\t') end += 1;
    tokens.push({ quoted: false, value: line.slice(index, end) });
    index = end;
  }
  return tokens;
}

export function parseLog(text) {
  const actions = [];
  const lines = text.split('\n');
  for (let number = 0; number < lines.length; number += 1) {
    const line = lines[number];
    if (line.length === 0 && number === lines.length - 1) continue;
    if (line.startsWith('# checkpoint')) {
      actions.push({ checkpoint: line.trim(), line: number + 1 });
      continue;
    }
    if (line.trim().length === 0) throw new Error(`blank line ${number + 1} is forbidden`);
    const tokens = tokenize(line);
    if (tokens.length < 3) throw new Error(`short action line ${number + 1}`);
    actions.push({
      at: tokens[0].value,
      actor: tokens[1].value,
      verb: tokens[2].value,
      args: tokens.slice(3),
      line: number + 1,
      raw: line,
    });
  }
  return actions;
}

function arg(action, index) {
  const token = action.args[index];
  return token === undefined ? undefined : token.value;
}

async function fixtureFile(relativePath) {
  const absolute = resolve(FIXTURES, relativePath);
  const bytes = await readFile(absolute);
  const extension = relativePath.split('.').pop().toLowerCase();
  const type = CONTENT_TYPES.get(extension) ?? 'application/octet-stream';
  return new File([bytes], basename(relativePath), { type });
}

export function createPersonaClient(baseUrl, appId, label) {
  const coordinator = new AuthCoordinator({
    appId,
    storage: createMemoryAuthCustodyStorage(),
    broadcastChannelFactory: null,
    hintStorage: null,
  });
  const client = new SnapbackClient(baseUrl, {
    authInvalidationProtocol: 1,
    authorityDescriptorProtocol: 1,
    authorizedLeaseProtocol: 1,
    rqsStore: null,
    authCoordinator: coordinator,
    clientStoreId: `clique-${label}`,
    storagePartition: `clique-${label}`,
  });
  return { client, coordinator };
}

export async function signInOrSignUp(client, email, password) {
  try {
    const result = await client.authPasswordSignup({ email, password });
    return { created: true, userId: result.session.userId };
  } catch {
    const result = await client.authPasswordSignIn({ email, password });
    return { created: false, userId: result.session.userId };
  }
}

async function uploadAsset(client, uploadRef, relativePath) {
  const file = await fixtureFile(relativePath);
  const assets = createAssetClient(client);
  const task = assets.start({ upload: uploadRef, file });
  const snapshot = await task.done;
  if (!snapshot.assetId) {
    throw new Error(`upload failed for ${relativePath}: ${JSON.stringify(snapshot.diagnostic)}`);
  }
  return snapshot.assetId;
}

class Replay {
  constructor(baseUrl, { log = () => {} } = {}) {
    this.baseUrl = baseUrl;
    this.appId = app.identity.app;
    this.actors = new Map();
    this.entities = new Map();
    this.logFn = log;
    this.stats = { applied: 0, skipped: 0 };
  }

  async actor(id) {
    const existing = this.actors.get(id);
    if (existing) return existing;
    throw new Error(`actor ${id} has not registered in this replay`);
  }

  async ensureActor(id, email, password) {
    const existing = this.actors.get(id);
    if (existing) return existing;
    const { client, coordinator } = createPersonaClient(this.baseUrl, this.appId, id);
    const outcome = await signInOrSignUp(client, email, password);
    const record = {
      id, client, coordinator, email, password, userId: outcome.userId, profileId: null,
    };
    this.actors.set(id, record);
    return record;
  }

  async hydrateLedger(client) {
    const result = await client.query(api.seedRefs, { args: {} });
    for (const row of result.rows) this.entities.set(row.logId, row.entityId);
  }

  async record(actor, logId, kind, entityId) {
    this.entities.set(logId, entityId);
    await actor.client.mutate(api.recordSeedRef, { args: { logId, kind, entityId } });
  }

  async profileIdFor(viewer, handle) {
    const result = await viewer.client.query(api.profileByHandle, { args: { handle } });
    if (result.rows.length === 0) throw new Error(`no profile for handle ${handle}`);
    return result.rows[0].profileId;
  }

  async apply(action) {
    if (action.checkpoint) return;
    const verb = action.verb;
    const actorId = action.actor;

    if (verb === 'register') {
      const email = arg(action, 0);
      const password = arg(action, 1);
      await this.ensureActor(actorId, email, password);
      this.stats.applied += 1;
      return;
    }

    const actor = await this.actor(actorId);

    if (verb === 'profile-set') {
      const values = {
        displayName: arg(action, 0),
        handle: arg(action, 1),
        bio: arg(action, 2),
        location: arg(action, 3),
        link: arg(action, 4),
      };
      const avatarPath = arg(action, 5);
      const existing = await actor.client.query(api.myProfile, { args: {} });
      if (existing.rows.length === 0) {
        const profileId = await actor.client.mutate(api.createProfile, { args: values });
        actor.profileId = profileId.result;
      } else {
        actor.profileId = existing.rows[0].profileId;
        const row = existing.rows[0];
        const unchanged = row.displayName === values.displayName
          && row.handle === values.handle
          && row.bio === values.bio
          && row.location === values.location
          && row.link === values.link;
        if (!unchanged) await actor.client.mutate(api.updateProfile, { args: values });
      }
      const avatarKey = `avatar:${actorId}`;
      if (avatarPath && !this.entities.has(avatarKey)) {
        const assetId = await uploadAsset(actor.client, api.avatarUpload, avatarPath);
        await actor.client.mutate(api.setAvatar, { args: { assetId } });
        await this.record(actor, avatarKey, 'asset', assetId);
      } else {
        this.stats.skipped += 1;
      }
      this.stats.applied += 1;
      return;
    }

    if (actor.profileId === null) {
      const mine = await actor.client.query(api.myProfile, { args: {} });
      if (mine.rows.length > 0) actor.profileId = mine.rows[0].profileId;
    }

    if (verb === 'follow') {
      const targetHandle = arg(action, 0);
      const intent = arg(action, 1);
      const targetProfileId = await this.profileIdFor(actor, targetHandle);
      await actor.client.mutate(api.setFollow, {
        args: {
          targetProfileId,
          following: intent === 'set',
          mutationId: String(arg(action, 2) ?? ''),
        },
      });
      this.stats.applied += 1;
      return;
    }

    if (verb === 'post') {
      const postLogId = arg(action, 0);
      if (this.entities.has(postLogId)) { this.stats.skipped += 1; return; }
      const shape = arg(action, 1);
      const text = arg(action, 2);
      const args = { text, kind: shape };
      if (shape === 'images') {
        const paths = String(arg(action, 3)).split(',');
        const assetIds = [];
        for (const path of paths) {
          assetIds.push(await uploadAsset(actor.client, api.postImageUpload, path));
        }
        args.imageAssetIds = assetIds;
      } else if (shape === 'video') {
        args.videoAssetId = await uploadAsset(actor.client, api.postVideoUpload, arg(action, 3));
      }
      const created = await actor.client.mutate(api.createPost, { args });
      await this.record(actor, postLogId, 'post', created.result);
      this.stats.applied += 1;
      return;
    }

    if (verb === 'reply') {
      const replyLogId = arg(action, 0);
      if (this.entities.has(replyLogId)) { this.stats.skipped += 1; return; }
      const parentLogId = arg(action, 1);
      const parentId = this.entities.get(parentLogId);
      if (!parentId) throw new Error(`unknown parent post ${parentLogId}`);
      const created = await actor.client.mutate(api.createPost, {
        args: { text: arg(action, 2), kind: 'text', parentId },
      });
      await this.record(actor, replyLogId, 'post', created.result);
      this.stats.applied += 1;
      return;
    }

    if (verb === 'like' || verb === 'repost') {
      const postId = this.entities.get(arg(action, 0));
      if (!postId) throw new Error(`unknown post ${arg(action, 0)}`);
      const intent = arg(action, 1) === 'set';
      const mutationId = String(arg(action, 2) ?? '');
      if (verb === 'like') {
        await actor.client.mutate(api.setLike, {
          args: { postId, liked: intent, mutationId },
        });
      } else {
        await actor.client.mutate(api.setRepost, {
          args: { postId, reposted: intent, mutationId },
        });
      }
      this.stats.applied += 1;
      return;
    }

    if (verb === 'dm-create') {
      const conversationLogId = arg(action, 0);
      const otherProfileId = await this.profileIdFor(actor, arg(action, 1));
      const created = await actor.client.mutate(api.createDm, { args: { otherProfileId } });
      if (!this.entities.has(conversationLogId)) {
        await this.record(actor, conversationLogId, 'conversation', created.result);
      } else {
        this.stats.skipped += 1;
      }
      this.stats.applied += 1;
      return;
    }

    if (verb === 'group-create') {
      const conversationLogId = arg(action, 0);
      if (this.entities.has(conversationLogId)) { this.stats.skipped += 1; return; }
      const secondMember = await this.profileIdFor(actor, arg(action, 1));
      const created = await actor.client.mutate(api.createGroup, {
        args: {
          title: arg(action, 2),
          description: arg(action, 3) ?? '',
          memberProfileIds: [secondMember],
        },
      });
      await this.record(actor, conversationLogId, 'conversation', created.result);
      this.stats.applied += 1;
      return;
    }

    if (verb === 'member-add') {
      const conversationId = this.entities.get(arg(action, 0));
      if (!conversationId) throw new Error(`unknown conversation ${arg(action, 0)}`);
      const profileId = await this.profileIdFor(actor, arg(action, 1));
      await actor.client.mutate(api.addMember, { args: { conversationId, profileId } });
      this.stats.applied += 1;
      return;
    }

    if (verb === 'send') {
      const messageLogId = arg(action, 0);
      if (this.entities.has(messageLogId)) { this.stats.skipped += 1; return; }
      const conversationId = this.entities.get(arg(action, 1));
      if (!conversationId) throw new Error(`unknown conversation ${arg(action, 1)}`);
      const args = { conversationId, text: arg(action, 2) };
      const quoteToken = arg(action, 3);
      if (typeof quoteToken === 'string' && quoteToken.startsWith('quote=')) {
        const quoteId = this.entities.get(quoteToken.slice('quote='.length));
        if (!quoteId) throw new Error(`unknown quoted message ${quoteToken}`);
        args.quoteId = quoteId;
      }
      const created = await actor.client.mutate(api.sendMessage, { args });
      await this.record(actor, messageLogId, 'message', created.result);
      this.stats.applied += 1;
      return;
    }

    throw new Error(`unsupported verb ${verb} at line ${action.line}`);
  }

  async dispose() {
    for (const actor of this.actors.values()) {
      try { await actor.client.close(); } catch { /* disposal is best effort */ }
    }
  }
}

export async function replayLogs(baseUrl, logPaths, options = {}) {
  const replay = new Replay(baseUrl, options);
  // Every persona's client is created lazily by `register`, but the ledger has
  // to be read before the first content action so a repeated segment is a
  // no-op. The first registered persona reads it.
  let hydrated = false;
  for (const logPath of logPaths) {
    const text = await readFile(logPath, 'utf8');
    const actions = parseLog(text);
    for (const action of actions) {
      await replay.apply(action);
      if (!hydrated && replay.actors.size > 0) {
        const first = replay.actors.values().next().value;
        await replay.hydrateLedger(first.client);
        hydrated = true;
      }
    }
  }
  const stats = { ...replay.stats, actors: replay.actors.size, entities: replay.entities.size };
  return { replay, stats };
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const baseUrl = process.env.CLIQUE_BACKEND ?? 'http://127.0.0.1:42160';
  const segments = process.argv.slice(2);
  if (segments.length === 0) {
    console.error('usage: node tools/replay.mjs <starter-log> [...]');
    process.exit(2);
  }
  const paths = segments.map((name) => (
    name.includes('/') ? resolve(name) : resolve(FIXTURES, name)
  ));
  const started = Date.now();
  const { replay, stats } = await replayLogs(baseUrl, paths);
  await replay.dispose();
  console.log(JSON.stringify({ ok: true, stats, ms: Date.now() - started }));
}
