import { useEffect, useState } from 'react';
import { ActivityIndicator, StyleSheet, Text, View } from 'react-native';
import { createSnapbackAppClient } from '@expo/snapback-client';
import type { SnapbackAppBindingV1 } from '@expo/snapback-client';
import { SnapbackProvider } from '@expo/snapback-react';

import { app } from '../snapback/generated/app.mjs';
import { palette, spacing, typeScale } from './social-ui';

/**
 * Clique runs its Expo Router client against a fixed-port local Snapback
 * backend rather than the random-port supervised Expo loop, so the deployment
 * binding is constructed here from the generated descriptor plus the pinned
 * origin. Identity facts still come from the generated descriptor; only the
 * origin is configuration.
 */
export const BACKEND_ORIGIN = (
  process.env.EXPO_PUBLIC_CLIQUE_BACKEND ?? 'http://127.0.0.1:42160'
);

function localBinding(): SnapbackAppBindingV1 {
  const issuedAt = new Date(Date.now() - 60_000).toISOString();
  const expiresAt = new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString();
  return {
    format: 'snapback.app-binding.v1',
    source: 'supervised-dev',
    descriptorIdentity: app.identity.descriptor,
    target: {
      app: app.identity.app,
      schema: app.identity.schema,
      functions: app.identity.functions,
      origin: BACKEND_ORIGIN,
      routing: 'loopback',
    },
    capabilities: { offered: [...app.capabilities.required] },
    provenance: {
      supervisorGeneration: `clique-local-${app.identity.descriptor.slice(0, 12)}`,
      issuedAt,
      expiresAt,
    },
    integrity: { channel: 'local-supervised-ipc' },
  };
}

type BootState =
  | { status: 'starting' }
  | { status: 'ready'; appClient: Awaited<ReturnType<typeof createSnapbackAppClient>> }
  | { status: 'error'; message: string };

export function CliqueBackendProvider({ children }: { children: React.ReactNode }) {
  const [boot, setBoot] = useState<BootState>({ status: 'starting' });

  useEffect(() => {
    let disposed = false;
    let created: Awaited<ReturnType<typeof createSnapbackAppClient>> | null = null;
    (async () => {
      try {
        const appClient = await createSnapbackAppClient({
          app: app as never,
          binding: localBinding(),
          platform: 'expo-web',
        });
        created = appClient;
        if (disposed) {
          appClient.dispose?.();
          return;
        }
        setBoot({ status: 'ready', appClient });
      } catch (error) {
        setBoot({
          status: 'error',
          message: error instanceof Error ? error.message : String(error),
        });
      }
    })();
    return () => {
      disposed = true;
      created?.dispose?.();
    };
  }, []);

  if (boot.status === 'starting') {
    return (
      <View style={styles.center} testID="sm-boot">
        <ActivityIndicator color={palette.primary} />
        <Text style={styles.caption}>Opening Clique…</Text>
      </View>
    );
  }
  if (boot.status === 'error') {
    return (
      <View style={styles.center} testID="sm-boot-error">
        <Text style={styles.title}>Clique could not start</Text>
        <Text selectable style={styles.caption}>{boot.message}</Text>
      </View>
    );
  }
  return (
    <SnapbackProvider
      appClient={boot.appClient}
      fallback={(state: { status: string }) => (
        <View style={styles.center} testID="sm-boot">
          <ActivityIndicator color={palette.primary} />
          <Text style={styles.caption}>Opening Clique… ({state.status})</Text>
        </View>
      )}
    >
      {children}
    </SnapbackProvider>
  );
}

const styles = StyleSheet.create({
  center: {
    alignItems: 'center',
    backgroundColor: palette.background,
    flex: 1,
    gap: spacing.sm,
    justifyContent: 'center',
    padding: spacing.xl,
  },
  title: { ...typeScale.title, color: palette.text },
  caption: { ...typeScale.footnote, color: palette.textMuted, textAlign: 'center' },
});
