import { useCallback, useMemo } from 'react';
import { useSnapbackMutation, useSnapbackQuery } from '@expo/snapback-react';

import api from '../snapback/generated/api.mjs';

export const NO_ARGS = Object.freeze({});

export type FeedRow = {
  entryId: string;
  entryKind: string;
  sortAt: number;
  repostedByName: string | null;
  postId: string;
  text: string;
  postKind: string;
  createdAt: number;
  authorProfileId: string;
  authorName: string;
  authorHandle: string;
  authorAvatarAssetId: string | null;
  imageAssetIds: readonly string[];
  videoAssetId: string | null;
  likeCount: number;
  repostCount: number;
  replyCount: number;
  viewerLiked: boolean;
  viewerReposted: boolean;
};

export type ProfileRow = {
  profileId: string;
  displayName: string;
  handle: string;
  bio: string;
  location: string;
  link: string;
  avatarAssetId: string | null;
  followerCount: number;
  followingCount: number;
  isSelf: boolean;
  viewerFollows: boolean;
};

export type ChatRow = {
  conversationId: string;
  kind: string;
  title: string;
  preview: string;
  avatarAssetId: string | null;
  unreadCount: number;
  updatedAt: number;
};

export type MessageRow = {
  messageId: string;
  conversationId: string;
  seq: number;
  senderProfileId: string;
  senderName: string;
  senderAvatarAssetId: string | null;
  isMine: boolean;
  text: string;
  kind: string;
  sentAt: number;
  quoteMessageId: string | null;
  quoteSenderName: string | null;
  quoteExcerpt: string | null;
  receipt: string;
};

export type ChatDetailRow = {
  conversationId: string;
  kind: string;
  title: string;
  description: string;
  viewerIsMember: boolean;
  viewerIsAdmin: boolean;
  viewerProfileId: string;
  messageCount: number;
  members: readonly {
    profileId: string;
    displayName: string;
    handle: string;
    role: string;
    avatarAssetId: string | null;
  }[];
};

function rowsOf<T>(state: { status: string; data?: unknown }): readonly T[] {
  if (state.status === 'ready' || state.status === 'refreshing') {
    return (state.data ?? []) as readonly T[];
  }
  return [];
}

export function useMyProfile() {
  const state = useSnapbackQuery(api.myProfile, NO_ARGS);
  const rows = rowsOf<ProfileRow>(state);
  return {
    status: state.status,
    profile: rows.length > 0 ? rows[0] : null,
    settled: state.status === 'ready' || state.status === 'refreshing',
  };
}

export function useProfile(handle: string) {
  const args = useMemo(() => ({ handle }), [handle]);
  const state = useSnapbackQuery(api.profileByHandle, args);
  const rows = rowsOf<ProfileRow>(state);
  return { status: state.status, profile: rows.length > 0 ? rows[0] : null };
}

export function useChats() {
  const state = useSnapbackQuery(api.myChats, NO_ARGS);
  return { status: state.status, chats: rowsOf<ChatRow>(state) };
}

export function useChatDetails(conversationId: string) {
  const args = useMemo(() => ({ conversationId }), [conversationId]);
  const state = useSnapbackQuery(api.chatDetails, args);
  const rows = rowsOf<ChatDetailRow>(state);
  return { status: state.status, details: rows.length > 0 ? rows[0] : null };
}

export function useChatMessages(conversationId: string, limit = 200) {
  const args = useMemo(() => ({ conversationId, limit }), [conversationId, limit]);
  const state = useSnapbackQuery(api.chatMessages, args);
  return { status: state.status, messages: rowsOf<MessageRow>(state) };
}

export function usePeopleSearch(query: string) {
  const args = useMemo(() => ({ query }), [query]);
  const state = useSnapbackQuery(api.peopleSearch, args);
  return {
    status: state.status,
    people: rowsOf<{
      profileId: string;
      displayName: string;
      handle: string;
      avatarAssetId: string | null;
      isSelf: boolean;
    }>(state),
  };
}

export function useThread(postId: string) {
  const args = useMemo(() => ({ postId }), [postId]);
  const state = useSnapbackQuery(api.thread, args);
  return { status: state.status, rows: rowsOf<FeedRow>(state) };
}

export function useAuthorPosts(handle: string, limit = 50) {
  const args = useMemo(() => ({ handle, limit }), [handle, limit]);
  const state = useSnapbackQuery(api.authorPosts, args);
  return { status: state.status, rows: rowsOf<FeedRow>(state) };
}

/** A client-minted mutation id keeps set-state intents idempotent under retry. */
export function mutationId(prefix: string, ...parts: (string | number | boolean)[]) {
  return `${prefix}:${parts.join(':')}`;
}

export function usePostActions() {
  const setLike = useSnapbackMutation(api.setLike);
  const setRepost = useSnapbackMutation(api.setRepost);
  const like = useCallback(
    (postId: string, liked: boolean) => setLike({
      postId,
      liked,
      mutationId: mutationId('like', postId, String(liked)),
    }),
    [setLike],
  );
  const repost = useCallback(
    (postId: string, reposted: boolean) => setRepost({
      postId,
      reposted,
      mutationId: mutationId('repost', postId, String(reposted)),
    }),
    [setRepost],
  );
  return { like, repost };
}

export function useFollowAction() {
  const setFollow = useSnapbackMutation(api.setFollow);
  return useCallback(
    (targetProfileId: string, following: boolean) => setFollow({
      targetProfileId,
      following,
      mutationId: mutationId('follow', targetProfileId, String(following)),
    }),
    [setFollow],
  );
}

export { api };
