import React, { useCallback, useRef } from 'react';
import { Image, Platform, StyleSheet, Text, View } from 'react-native';
import { useSnapbackAssetImage, useSnapbackAssetUpload } from '@expo/snapback-react';

import { Avatar, palette, radii, spacing, typeScale } from './social-ui';
import api from '../snapback/generated/api.mjs';

/** The canonical delivery ladder resolves the URL; no hand-built asset routes. */
export function useAssetSrc(assetId: string | null | undefined, maxWidth = 640) {
  const image = useSnapbackAssetImage({ assetId: assetId ?? null, maxWidth });
  return image.src ?? undefined;
}

export function AssetAvatar({
  assetId,
  label,
  size = 40,
}: {
  assetId: string | null | undefined;
  label: string;
  size?: number;
}) {
  const uri = useAssetSrc(assetId, Math.max(96, size * 2));
  return <Avatar label={label} size={size} {...(uri ? { uri } : {})} />;
}

export function AssetImage({
  assetId,
  style,
  accessibilityLabel,
  testID,
}: {
  assetId: string;
  style?: object;
  accessibilityLabel?: string;
  testID?: string;
}) {
  const uri = useAssetSrc(assetId, 1024);
  if (!uri) return <View style={[styles.mediaPlaceholder, style]} testID={testID} />;
  return (
    <Image
      accessibilityLabel={accessibilityLabel ?? 'Image'}
      resizeMode="cover"
      source={{ uri }}
      style={[styles.media, style]}
      testID={testID}
    />
  );
}

/**
 * Web video element. The frozen kit renders a poster + play glyph for feed
 * video; the lane owns actual playback, so this is a real <video> on web.
 */
export function AssetVideo({ assetId, testID }: { assetId: string; testID?: string }) {
  const uri = useAssetSrc(assetId, 1280);
  if (Platform.OS !== 'web') {
    return <View style={styles.mediaPlaceholder} testID={testID} />;
  }
  if (!uri) return <View style={styles.mediaPlaceholder} testID={testID} />;
  return React.createElement('video', {
    src: uri,
    controls: true,
    muted: true,
    playsInline: true,
    'data-testid': testID,
    style: { width: '100%', borderRadius: radii.md, background: '#000' },
  });
}

export type PickedFile = { file: File; name: string; kind: 'image' | 'video' };

/**
 * A plain DOM file input. The frozen contract pins no compose media-picker
 * test ID, so this is a lane-owned affordance (extras are permitted) that the
 * acceptance suite drives with setInputFiles.
 */
export function FilePicker({
  testID,
  accept,
  multiple = false,
  label,
  onPick,
}: {
  testID: string;
  accept: string;
  multiple?: boolean;
  label: string;
  onPick: (files: PickedFile[]) => void;
}) {
  const ref = useRef<unknown>(null);
  const handleChange = useCallback((event: { target: { files: FileList | null } }) => {
    const list = event.target.files;
    if (!list) return;
    const picked: PickedFile[] = [];
    for (let index = 0; index < list.length; index += 1) {
      const file = list.item(index);
      if (!file) continue;
      picked.push({
        file,
        name: file.name,
        kind: file.type.startsWith('video/') ? 'video' : 'image',
      });
    }
    onPick(picked);
  }, [onPick]);

  if (Platform.OS !== 'web') {
    return <Text style={styles.hint}>{label} (web only)</Text>;
  }
  return React.createElement(
    'label',
    { style: { display: 'inline-flex', flexDirection: 'column', gap: 4 } },
    React.createElement('span', { style: { font: '13px sans-serif', color: palette.textMuted } }, label),
    React.createElement('input', {
      ref,
      type: 'file',
      accept,
      multiple,
      'data-testid': testID,
      onChange: handleChange,
      style: { font: '13px sans-serif' },
    }),
  );
}

export type UploadIntent = 'avatar' | 'postImage' | 'postVideo';

const INTENTS = {
  avatar: api.avatarUpload,
  postImage: api.postImageUpload,
  postVideo: api.postVideoUpload,
} as const;

export function useUploader(intent: UploadIntent) {
  const hook = useSnapbackAssetUpload({ upload: INTENTS[intent] as never });
  return useCallback(async (file: File): Promise<string> => {
    const task = hook.start(file as never);
    const snapshot = await task.done;
    if (!snapshot.assetId) {
      throw new Error(snapshot.diagnostic?.message ?? 'upload failed');
    }
    return snapshot.assetId;
  }, [hook]);
}

const styles = StyleSheet.create({
  media: {
    backgroundColor: palette.surfaceStrong,
    borderRadius: radii.md,
    width: '100%',
  },
  mediaPlaceholder: {
    aspectRatio: 16 / 10,
    backgroundColor: palette.surfaceStrong,
    borderRadius: radii.md,
    width: '100%',
  },
  hint: { ...typeScale.footnote, color: palette.textMuted, marginTop: spacing.xs },
});
