import { useCallback, useMemo, useState } from 'react';
import { ActivityIndicator, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';
import {
  useSnapbackAuth,
  useSnapbackCurrentPrincipal,
  useSnapbackMutation,
  useSnapbackQuery,
} from '@expo/snapback-react';

import { AuthForm, palette, radii, spacing, typeScale } from './social-ui';
import api, { useMyProfile } from './data';

function messageOf(error: unknown): string {
  if (error && typeof error === 'object') {
    const diagnostic = (error as { diagnostic?: { code?: string; message?: string; details?: { appCode?: string } } }).diagnostic;
    const appCode = diagnostic?.details?.appCode;
    if (appCode === 'HANDLE_TAKEN') return 'That handle is already taken.';
    if (appCode === 'HANDLE_INVALID') return 'Handles are 3–20 characters of a–z, 0–9 or _.';
    if (appCode === 'FIELD_TOO_LONG') return 'One of those fields is too long.';
    if (appCode === 'PROFILE_EXISTS') return 'This account already has a profile.';
    const code = diagnostic?.code ?? '';
    if (code.includes('PASSWORD_POLICY')) return 'Passwords must be at least 8 characters.';
    if (code.includes('IDENTITY_EXISTS') || code.includes('ALREADY')) {
      return 'That email is already registered.';
    }
    if (code.includes('CREDENTIAL') || code.includes('SIGNIN')) {
      return 'Email or password is incorrect.';
    }
    if (diagnostic?.message) return diagnostic.message;
  }
  if (error instanceof Error) return error.message;
  return String(error);
}

/** Signed-out shell: sign in, or sign up with the brief's profile fields. */
function AuthScreen() {
  const auth = useSnapbackAuth();
  const [mode, setMode] = useState<'sign-in' | 'sign-up'>('sign-in');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [handle, setHandle] = useState('');
  const [error, setError] = useState<string | undefined>(undefined);
  const [submitting, setSubmitting] = useState(false);
  const handleArgs = useMemo(() => ({ handle: handle.trim().toLowerCase() }), [handle]);
  const availability = useSnapbackQuery(api.handleAvailable, handleArgs);

  const submit = useCallback(async (nextEmail: string, nextPassword: string) => {
    setError(undefined);
    setSubmitting(true);
    try {
      if (mode === 'sign-in') {
        await auth.signInWithPassword({ email: nextEmail.trim(), password: nextPassword });
        return;
      }
      if (nextPassword.length < 8) {
        setError('Passwords must be at least 8 characters.');
        return;
      }
      if (displayName.trim().length === 0) {
        setError('A display name is required.');
        return;
      }
      const rows = (availability.status === 'ready' || availability.status === 'refreshing')
        ? (availability.data as readonly { available: boolean; valid: boolean }[])
        : [];
      const check = rows.length > 0 ? rows[0] : null;
      if (!check || !check.valid) {
        setError('Handles are 3–20 characters of a–z, 0–9 or _.');
        return;
      }
      if (!check.available) {
        setError('That handle is already taken.');
        return;
      }
      await auth.signUpWithPassword({ email: nextEmail.trim(), password: nextPassword });
    } catch (caught) {
      setError(messageOf(caught));
    } finally {
      setSubmitting(false);
    }
  }, [auth, availability.data, availability.status, displayName, mode]);

  return (
    <ScrollView contentContainerStyle={styles.authPage}>
      <View style={styles.authCard}>
        <AuthForm
          email={email}
          mode={mode}
          onChangeEmail={setEmail}
          onChangePassword={setPassword}
          onSubmit={submit}
          onToggleMode={() => {
            setError(undefined);
            setMode((value) => (value === 'sign-in' ? 'sign-up' : 'sign-in'));
          }}
          password={password}
          submitting={submitting}
          {...(error ? { errorText: error } : {})}
        />
        {mode === 'sign-up' ? (
          <View style={styles.extraFields} testID="sm-auth-profile-fields">
            <Text style={styles.fieldLabel}>Display name</Text>
            <TextInput
              accessibilityLabel="Display name"
              maxLength={50}
              onChangeText={setDisplayName}
              placeholder="Your name"
              placeholderTextColor={palette.textFaint}
              style={styles.input}
              testID="sm-auth-displayname"
              value={displayName}
            />
            <Text style={styles.fieldLabel}>Handle</Text>
            <TextInput
              accessibilityLabel="Handle"
              autoCapitalize="none"
              maxLength={20}
              onChangeText={setHandle}
              placeholder="handle"
              placeholderTextColor={palette.textFaint}
              style={styles.input}
              testID="sm-auth-handle"
              value={handle}
            />
          </View>
        ) : null}
      </View>
    </ScrollView>
  );
}

/**
 * A principal exists but has no profile yet (signup completes in two steps so a
 * duplicate handle never strands a half-made account without a visible error).
 */
function ProfileSetup({ pendingName, pendingHandle }: {
  pendingName: string;
  pendingHandle: string;
}) {
  const createProfile = useSnapbackMutation(api.createProfile);
  const auth = useSnapbackAuth();
  const [displayName, setDisplayName] = useState(pendingName);
  const [handle, setHandle] = useState(pendingHandle);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const submit = useCallback(async () => {
    setBusy(true);
    setError(null);
    try {
      await createProfile({
        displayName: displayName.trim(),
        handle: handle.trim().toLowerCase(),
        bio: '',
        location: '',
        link: '',
      });
    } catch (caught) {
      setError(messageOf(caught));
    } finally {
      setBusy(false);
    }
  }, [createProfile, displayName, handle]);

  return (
    <ScrollView contentContainerStyle={styles.authPage}>
      <View style={styles.authCard} testID="sm-profile-setup">
        <Text style={styles.title}>Finish your profile</Text>
        <Text style={styles.fieldLabel}>Display name</Text>
        <TextInput
          accessibilityLabel="Display name"
          maxLength={50}
          onChangeText={setDisplayName}
          style={styles.input}
          testID="sm-setup-displayname"
          value={displayName}
        />
        <Text style={styles.fieldLabel}>Handle</Text>
        <TextInput
          accessibilityLabel="Handle"
          autoCapitalize="none"
          maxLength={20}
          onChangeText={setHandle}
          style={styles.input}
          testID="sm-setup-handle"
          value={handle}
        />
        {error ? <Text style={styles.error} testID="sm-setup-error">{error}</Text> : null}
        <Text
          accessibilityRole="button"
          onPress={busy ? undefined : submit}
          style={styles.primary}
          testID="sm-setup-submit"
        >
          {busy ? 'Saving…' : 'Create profile'}
        </Text>
        <Text
          accessibilityRole="button"
          onPress={() => void auth.signOut()}
          style={styles.secondary}
          testID="sm-setup-cancel"
        >
          Cancel and sign out
        </Text>
      </View>
    </ScrollView>
  );
}

export function AuthGate({ children }: { children: React.ReactNode }) {
  const principal = useSnapbackCurrentPrincipal();
  const profile = useMyProfile();

  if (principal.status === 'loading' || principal.status === 'refreshing') {
    return (
      <View style={styles.center} testID="sm-auth-loading">
        <ActivityIndicator color={palette.primary} />
      </View>
    );
  }
  if (principal.status !== 'authenticated') return <AuthScreen />;
  if (!profile.settled) {
    return (
      <View style={styles.center} testID="sm-profile-loading">
        <ActivityIndicator color={palette.primary} />
      </View>
    );
  }
  if (!profile.profile) return <ProfileSetup pendingHandle="" pendingName="" />;
  return <>{children}</>;
}

const styles = StyleSheet.create({
  authPage: {
    alignItems: 'center',
    backgroundColor: palette.surface,
    flexGrow: 1,
    justifyContent: 'center',
    padding: spacing.xl,
  },
  authCard: {
    backgroundColor: palette.background,
    borderRadius: radii.lg,
    maxWidth: 420,
    padding: spacing.md,
    width: '100%',
  },
  extraFields: { paddingHorizontal: spacing.xl, paddingBottom: spacing.xl },
  fieldLabel: { ...typeScale.footnote, color: palette.textMuted, marginBottom: spacing.xs },
  input: {
    ...typeScale.body,
    backgroundColor: palette.surface,
    borderRadius: radii.md,
    color: palette.text,
    marginBottom: spacing.md,
    paddingHorizontal: spacing.lg,
    paddingVertical: spacing.md,
  },
  title: { ...typeScale.title, color: palette.text, marginBottom: spacing.md },
  error: { ...typeScale.footnote, color: palette.danger, marginBottom: spacing.sm },
  primary: {
    ...typeScale.body,
    backgroundColor: palette.primary,
    borderRadius: radii.md,
    color: palette.textInverse,
    fontWeight: '700',
    paddingVertical: spacing.md,
    textAlign: 'center',
  },
  secondary: {
    ...typeScale.footnote,
    color: palette.textMuted,
    marginTop: spacing.md,
    textAlign: 'center',
  },
  center: {
    alignItems: 'center',
    backgroundColor: palette.background,
    flex: 1,
    justifyContent: 'center',
  },
});
