import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Linking, Platform, Pressable, StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { useSnapbackQuery } from '@expo/snapback-react';

import { FeedCard, palette, radii, spacing, typeScale } from './social-ui';
import { AssetImage, AssetVideo, useAssetSrc } from './media';
import api, { FeedRow, usePostActions } from './data';

export const PAGE_SIZE = 20;

export function openLink(url: string) {
  // Brief global ruling: links open the system browser. No unfurling, no
  // preview card.
  if (Platform.OS === 'web' && typeof window !== 'undefined') {
    window.open(url, '_blank', 'noopener,noreferrer');
    return;
  }
  void Linking.openURL(url);
}

export function FeedItem({ row, showMedia = true }: { row: FeedRow; showMedia?: boolean }) {
  const router = useRouter();
  const { like, repost } = usePostActions();
  const avatarUri = useAssetSrc(row.authorAvatarAssetId, 96);
  const imageUris = row.imageAssetIds.map((assetId) => assetId);

  return (
    <View testID="sm-feed-entry">
      <FeedCard
        authorHandle={row.authorHandle}
        authorName={row.authorName}
        likeCount={row.likeCount}
        liked={row.viewerLiked}
        onPress={() => router.push(`/thread/${row.postId}`)}
        onPressAuthor={() => router.push(`/profile/${row.authorHandle}`)}
        onPressLike={() => void like(row.postId, !row.viewerLiked)}
        onPressLink={openLink}
        onPressReply={() => router.push(`/thread/${row.postId}`)}
        onPressRepost={() => void repost(row.postId, !row.viewerReposted)}
        replyCount={row.replyCount}
        repostCount={row.repostCount}
        reposted={row.viewerReposted}
        text={row.text}
        timestamp={formatTime(row.createdAt)}
        {...(avatarUri ? { authorAvatarUri: avatarUri } : {})}
        {...(row.repostedByName ? { repostedByName: row.repostedByName } : {})}
      />
      {showMedia && imageUris.length > 0 ? (
        <View style={styles.mediaRow} testID="sm-feed-images">
          {imageUris.map((assetId) => (
            <View key={assetId} style={styles.mediaCell}>
              <AssetImage
                accessibilityLabel="Post image"
                assetId={assetId}
                testID="sm-feed-image"
              />
            </View>
          ))}
        </View>
      ) : null}
      {showMedia && row.videoAssetId ? (
        <View style={styles.mediaRow}>
          <AssetVideo assetId={row.videoAssetId} testID="sm-feed-video" />
        </View>
      ) : null}
    </View>
  );
}

export function formatTime(epochMs: number) {
  const date = new Date(epochMs);
  const hours = String(date.getHours()).padStart(2, '0');
  const minutes = String(date.getMinutes()).padStart(2, '0');
  return `${hours}:${minutes}`;
}

/**
 * One keyset page of the feed. Page 0 is live and unbounded above; later pages
 * pin an inclusive `beforeSortAt` cursor so a concurrent insert can shift the
 * window without opening a gap. The parent de-duplicates by `entryId`.
 */
function FeedPageLoader({
  scope,
  cursor,
  index,
  onRows,
}: {
  scope: 'following' | 'global';
  cursor: number | null;
  index: number;
  onRows: (index: number, rows: readonly FeedRow[]) => void;
}) {
  const args = useMemo(
    () => (cursor === null
      ? { scope, limit: PAGE_SIZE }
      : { scope, limit: PAGE_SIZE + 1, beforeSortAt: cursor }),
    [cursor, scope],
  );
  const state = useSnapbackQuery(api.feedPage, args);
  const rows = (state.status === 'ready' || state.status === 'refreshing')
    ? (state.data as readonly FeedRow[])
    : null;
  useEffect(() => {
    if (rows) onRows(index, rows);
  }, [index, onRows, rows]);
  return null;
}

export function Feed({ scope }: { scope: 'following' | 'global' }) {
  const [cursors, setCursors] = useState<(number | null)[]>([null]);
  const [pages, setPages] = useState<Record<number, readonly FeedRow[]>>({});
  const pagesRef = useRef(pages);
  pagesRef.current = pages;

  useEffect(() => {
    setCursors([null]);
    setPages({});
  }, [scope]);

  const onRows = useCallback((index: number, rows: readonly FeedRow[]) => {
    setPages((current) => (current[index] === rows ? current : { ...current, [index]: rows }));
  }, []);

  const merged = useMemo(() => {
    const seen = new Set<string>();
    const out: FeedRow[] = [];
    for (const index of Object.keys(pages).map(Number).sort((a, b) => a - b)) {
      for (const row of pages[index] ?? []) {
        if (seen.has(row.entryId)) continue;
        seen.add(row.entryId);
        out.push(row);
      }
    }
    out.sort((left, right) => right.sortAt - left.sortAt);
    return out;
  }, [pages]);

  const lastPageRows = pages[cursors.length - 1] ?? [];
  const canLoadMore = lastPageRows.length >= (cursors.length === 1 ? PAGE_SIZE : PAGE_SIZE + 1);

  const loadMore = useCallback(() => {
    const current = pagesRef.current;
    const lastIndex = Object.keys(current).map(Number).sort((a, b) => a - b).pop() ?? 0;
    const rows = current[lastIndex] ?? [];
    if (rows.length === 0) return;
    const nextCursor = rows[rows.length - 1].sortAt;
    setCursors((existing) => (
      existing[existing.length - 1] === nextCursor ? existing : [...existing, nextCursor]
    ));
  }, []);

  const handleScroll = useCallback((event: {
    nativeEvent: {
      contentOffset: { y: number };
      contentSize: { height: number };
      layoutMeasurement: { height: number };
    };
  }) => {
    const { contentOffset, contentSize, layoutMeasurement } = event.nativeEvent;
    if (contentOffset.y + layoutMeasurement.height >= contentSize.height - 240) loadMore();
  }, [loadMore]);

  return {
    rows: merged,
    canLoadMore,
    loadMore,
    handleScroll,
    loaders: cursors.map((cursor, index) => (
      <FeedPageLoader
        cursor={cursor}
        index={index}
        key={`${scope}:${index}:${cursor ?? 'head'}`}
        onRows={onRows}
        scope={scope}
      />
    )),
  };
}

export function LoadMoreButton({ onPress, visible }: { onPress: () => void; visible: boolean }) {
  if (!visible) return null;
  return (
    <Pressable
      accessibilityRole="button"
      onPress={onPress}
      style={styles.loadMore}
      testID="sm-feed-load-more"
    >
      <Text style={styles.loadMoreText}>Load more</Text>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  mediaRow: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: spacing.sm,
    paddingBottom: spacing.md,
    paddingHorizontal: spacing.lg,
  },
  mediaCell: { flexBasis: '48%', flexGrow: 1 },
  loadMore: {
    alignItems: 'center',
    backgroundColor: palette.surface,
    borderRadius: radii.md,
    margin: spacing.lg,
    paddingVertical: spacing.md,
  },
  loadMoreText: { ...typeScale.body, color: palette.text, fontWeight: '600' },
});
