import { useCallback, useState } from 'react';
import { ScrollView, StyleSheet, Text, View } from 'react-native';
import { useLocalSearchParams } from 'expo-router';
import { useSnapbackMutation } from '@expo/snapback-react';

import { Composer, palette, spacing, typeScale } from '../src/social-ui';
import { FeedItem, LoadMoreButton, useFeed } from '../src/feed';
import { FilePicker, PickedFile, useUploader } from '../src/media';
import api from '../src/data';

export default function FeedScreen() {
  const params = useLocalSearchParams<{ tab?: string }>();
  const scope: 'following' | 'global' = params.tab === 'global' ? 'global' : 'following';
  const feed = useFeed(scope);
  const createPost = useSnapbackMutation(api.createPost);
  const uploadImage = useUploader('postImage');
  const uploadVideo = useUploader('postVideo');
  const [draft, setDraft] = useState('');
  const [picked, setPicked] = useState<PickedFile[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [sending, setSending] = useState(false);

  const submit = useCallback(async () => {
    setError(null);
    setSending(true);
    try {
      const images = picked.filter((item) => item.kind === 'image');
      const video = picked.find((item) => item.kind === 'video');
      if (images.length > 0 && video) throw new Error('A post never mixes images and video.');
      if (images.length > 4) throw new Error('A post carries at most 4 images.');
      const args: {
        text: string;
        kind: string;
        imageAssetIds?: string[];
        videoAssetId?: string;
      } = { text: draft, kind: 'text' };
      if (video) {
        args.kind = 'video';
        args.videoAssetId = await uploadVideo(video.file);
      } else if (images.length > 0) {
        args.kind = 'images';
        const ids: string[] = [];
        for (const image of images) ids.push(await uploadImage(image.file));
        args.imageAssetIds = ids;
      }
      await createPost(args);
      setDraft('');
      setPicked([]);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    } finally {
      setSending(false);
    }
  }, [createPost, draft, picked, uploadImage, uploadVideo]);

  return (
    <View style={styles.screen}>
      {feed.loaders}
      <View style={styles.composer}>
        <Composer
          maxLength={500}
          onChangeText={setDraft}
          onSend={() => void submit()}
          sending={sending}
          value={draft}
          variant="post"
          {...(picked.length > 0
            ? {
              attachments: picked.map((item) => ({ uri: item.name, kind: item.kind })),
              onRemoveAttachment: (index: number) => setPicked(
                (current) => current.filter((_, position) => position !== index),
              ),
            }
            : {})}
        />
        <View style={styles.pickerRow}>
          <FilePicker
            accept="image/png,image/jpeg,image/webp"
            label="Add up to 4 images"
            multiple
            onPick={(files) => setPicked(files)}
            testID="sm-compose-file-images"
          />
          <FilePicker
            accept="video/mp4"
            label="Add one video"
            onPick={(files) => setPicked(files.slice(0, 1))}
            testID="sm-compose-file-video"
          />
        </View>
        {error ? <Text style={styles.error} testID="sm-compose-error">{error}</Text> : null}
      </View>
      <ScrollView
        onScroll={feed.handleScroll}
        scrollEventThrottle={64}
        style={styles.list}
        testID="sm-feed-scroll"
      >
        {feed.rows.map((row) => <FeedItem key={row.entryId} row={row} />)}
        {feed.rows.length === 0 ? (
          <Text style={styles.empty} testID="sm-feed-empty">
            {scope === 'following'
              ? 'Follow some accounts, or post something yourself.'
              : 'Nothing here yet.'}
          </Text>
        ) : null}
        <LoadMoreButton onPress={feed.loadMore} visible={feed.canLoadMore} />
      </ScrollView>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { backgroundColor: palette.background, flex: 1 },
  composer: {
    borderBottomColor: palette.border,
    borderBottomWidth: StyleSheet.hairlineWidth,
