import { useCallback, useEffect, useState } from 'react';
import { ScrollView, StyleSheet, Text, View } from 'react-native';
import { useRouter } from 'expo-router';
import { useSnapbackMutation } from '@expo/snapback-react';

import { ProfileForm, palette, spacing, typeScale } from '../../src/social-ui';
import { FilePicker, useAssetSrc, useUploader } from '../../src/media';
import api, { useMyProfile } from '../../src/data';

const EMPTY = { displayName: '', handle: '', bio: '', location: '', link: '' };

export default function EditProfileScreen() {
  const router = useRouter();
  const { profile } = useMyProfile();
  const updateProfile = useSnapbackMutation(api.updateProfile);
  const setAvatar = useSnapbackMutation(api.setAvatar);
  const uploadAvatar = useUploader('avatar');
  const [values, setValues] = useState(EMPTY);
  const [loaded, setLoaded] = useState(false);
  const [error, setError] = useState<string | undefined>(undefined);
  const [saving, setSaving] = useState(false);
  const avatarUri = useAssetSrc(profile?.avatarAssetId ?? null, 192);

  useEffect(() => {
    if (loaded || !profile) return;
    setValues({
      displayName: profile.displayName,
      handle: profile.handle,
      bio: profile.bio,
      location: profile.location,
      link: profile.link,
    });
    setLoaded(true);
  }, [loaded, profile]);

  const save = useCallback(async (next: typeof EMPTY) => {
    setError(undefined);
    setSaving(true);
    try {
      await updateProfile(next);
      router.push(`/profile/${next.handle.trim().toLowerCase()}`);
    } catch (caught) {
      const diagnostic = (caught as { diagnostic?: { details?: { appCode?: string }; message?: string } }).diagnostic;
      const appCode = diagnostic?.details?.appCode;
      setError(
        appCode === 'HANDLE_TAKEN'
          ? 'That handle is already taken.'
          : appCode === 'HANDLE_INVALID'
            ? 'Handles are 3–20 characters of a–z, 0–9 or _.'
            : (diagnostic?.message ?? (caught instanceof Error ? caught.message : String(caught))),
      );
    } finally {
      setSaving(false);
    }
  }, [router, updateProfile]);

  const pickAvatar = useCallback(async (files: { file: File }[]) => {
    if (files.length === 0) return;
    setError(undefined);
    try {
      const assetId = await uploadAvatar(files[0].file);
      await setAvatar({ assetId });
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    }
  }, [setAvatar, uploadAvatar]);

  return (
    <ScrollView style={styles.screen} testID="sm-profile-edit-screen">
      <Text style={styles.screenTitle}>Edit profile</Text>
      <ProfileForm
        avatarUri={avatarUri}
        mode="edit"
        onChange={(patch) => setValues((current) => ({ ...current, ...patch }))}
        onPressSave={(next) => void save(next)}
        saving={saving}
        values={values}
        {...(error ? { errorText: error } : {})}
      />
      <View style={styles.avatarPicker}>
        <FilePicker
          accept="image/png,image/jpeg,image/webp"
          label="Replace avatar"
          onPick={(files) => void pickAvatar(files)}
          testID="sm-profile-file-avatar"
        />
      </View>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  screen: { backgroundColor: palette.background, flex: 1 },
  screenTitle: {
    ...typeScale.title,
    color: palette.text,
    paddingHorizontal: spacing.lg,
    paddingTop: spacing.lg,
  },
  avatarPicker: { paddingBottom: spacing.xxl, paddingHorizontal: spacing.lg },
});
