import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { skip, useSnapbackMutation, useSnapbackPresence } from '@expo/snapback-react';

import {
  Composer,
  MessageBubble,
  TypingIndicator,
  palette,
  spacing,
  typeScale,
} from '../../../src/social-ui';
import { AssetAvatar } from '../../../src/media';
import api, {
  MessageRow,
  useChatDetails,
  useChatMessages,
  useMyProfile,
} from '../../../src/data';
import { ephemeral } from '../../../snapback/generated/api.mjs';

const TYPING_IDLE_MS = 1_200;

export default function ConversationScreen() {
  const { conversationId } = useLocalSearchParams<{ conversationId: string }>();
  const id = String(conversationId ?? '');
  const router = useRouter();
  const { profile } = useMyProfile();
  const { details } = useChatDetails(id);
  const { messages } = useChatMessages(id);
  const send = useSnapbackMutation(api.sendMessage);
  const markChatState = useSnapbackMutation(api.markChatState);
  const [draft, setDraft] = useState('');
  const [replyTo, setReplyTo] = useState<MessageRow | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [sending, setSending] = useState(false);
  const [typingActive, setTypingActive] = useState(false);
  const [highlighted, setHighlighted] = useState<string | null>(null);
  const scrollRef = useRef<ScrollView | null>(null);
  const idleTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Typing presence: published while the composer is actively being typed in,
  // released within the ephemeral lease once keystrokes stop.
  const presenceScope = useMemo(() => ({ conversationId: id }), [id]);
  const presenceValue = useMemo(
    () => (typingActive && profile ? { displayName: profile.displayName } : skip),
    [profile, typingActive],
  );
  const presence = useSnapbackPresence(ephemeral.typing, {
    scope: presenceScope,
    value: presenceValue,
    ttlMs: 3_000,
  });

  const typingNames = useMemo(() => {
    if (presence.status !== 'ready' && presence.status !== 'stale') return [];
    const selfKey = presence.selfKey;
    return [...new Set(
      presence.entries
        .filter((entry: { key: string }) => entry.key !== selfKey)
        .map((entry: { value: { displayName: string } }) => entry.value.displayName),
    )];
  }, [presence]);

  const onChangeText = useCallback((text: string) => {
    setDraft(text);
    setTypingActive(text.length > 0);
    if (idleTimer.current) clearTimeout(idleTimer.current);
    idleTimer.current = setTimeout(() => setTypingActive(false), TYPING_IDLE_MS);
  }, []);

  useEffect(() => () => {
    if (idleTimer.current) clearTimeout(idleTimer.current);
  }, []);

  // Receipts: fetching the conversation is `delivered`; having it open is
  // `read`. Both watermarks are monotonic server-side.
  const highestSeq = messages.length > 0 ? messages[messages.length - 1].seq : 0;
  useEffect(() => {
    if (!id || highestSeq === 0) return;
    void markChatState({ conversationId: id, deliveredSeq: highestSeq, readSeq: highestSeq })
      .catch(() => undefined);
  }, [highestSeq, id, markChatState]);

  const submit = useCallback(async () => {
    const text = draft.trim();
    if (text.length === 0) return;
    setError(null);
    setSending(true);
    try {
      await send({
        conversationId: id,
        text,
        ...(replyTo ? { quoteId: replyTo.messageId } : {}),
      });
      setDraft('');
      setReplyTo(null);
      setTypingActive(false);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    } finally {
      setSending(false);
    }
  }, [draft, id, replyTo, send]);

  const jumpToQuote = useCallback((quoteMessageId: string) => {
    setHighlighted(quoteMessageId);
    const index = messages.findIndex((row) => row.messageId === quoteMessageId);
    if (index >= 0 && scrollRef.current) {
      // Bring the original into view; the quoted excerpt is the affordance.
      scrollRef.current.scrollTo({ y: Math.max(0, index * 96 - 80), animated: false });
    }
  }, [messages]);

  if (!details) {
    return (
      <View style={styles.screen}>
        <Text style={styles.empty} testID="sm-convo-missing">This conversation is unavailable.</Text>
      </View>
    );
  }

  return (
    <View style={styles.screen}>
      <View style={styles.header}>
        <View style={styles.headerBody}>
          <Text style={styles.title} testID="sm-convo-title">{details.title}</Text>
          <Text style={styles.subtitle}>
            {details.kind === 'group' ? `${details.members.length} members` : 'Direct message'}
          </Text>
        </View>
        <Pressable
          accessibilityRole="button"
          onPress={() => router.push(`/chat/${id}/settings`)}
          testID="sm-convo-settings"
        >
          <Text style={styles.settings}>Chat settings</Text>
        </Pressable>
      </View>

      <ScrollView ref={scrollRef} style={styles.list} testID="sm-convo-scroll">
        {messages.map((message) => (
          <View key={message.messageId} style={styles.bubbleRow}>
            {!message.isMine ? (
              <View testID="sm-convo-sender-avatar">
                <AssetAvatar
                  assetId={message.senderAvatarAssetId}
                  label={message.senderName}
                  size={28}
                />
              </View>
            ) : null}
            <View style={styles.bubbleColumn}>
              <MessageBubble
                isMine={message.isMine}
                senderName={message.senderName}
                showSender={!message.isMine && details.kind === 'group'}
                text={message.text}
                timestamp={new Date(message.sentAt).toISOString().slice(11, 16)}
                {...(message.quoteMessageId
                  ? {
                    quote: {
                      senderName: message.quoteSenderName ?? 'Unknown',
                      excerpt: message.quoteExcerpt ?? '',
                    },
                    onPressQuote: () => jumpToQuote(message.quoteMessageId as string),
                  }
                  : {})}
                {...(message.isMine ? { receipt: message.receipt as never } : {})}
              />
              <View style={styles.messageActions}>
                <Pressable
                  accessibilityLabel="Reply"
                  accessibilityRole="button"
                  onPress={() => setReplyTo(message)}
                  testID="sm-convo-quote"
                >
                  <Text style={styles.action}>Reply</Text>
                </Pressable>
                {message.isMine ? (
                  <Text style={styles.receipt} testID="sm-convo-receipt">
                    {message.receipt}
                  </Text>
                ) : null}
                {highlighted === message.messageId ? (
                  <Text style={styles.action} testID="sm-convo-highlight">•</Text>
                ) : null}
              </View>
            </View>
          </View>
        ))}
      </ScrollView>

      <View style={styles.composerShell}>
        <TypingIndicator names={typingNames} visible={typingNames.length > 0} />
        {replyTo ? (
          <View style={styles.replyBar} testID="sm-convo-reply-bar">
            <Text numberOfLines={1} style={styles.replyText}>
              Replying to {replyTo.senderName}: {replyTo.text}
            </Text>
            <Pressable accessibilityRole="button" onPress={() => setReplyTo(null)}>
              <Text style={styles.action}>Cancel</Text>
            </Pressable>
          </View>
        ) : null}
        {error ? <Text style={styles.error} testID="sm-convo-error">{error}</Text> : null}
        <Composer
          maxLength={2000}
          onChangeText={onChangeText}
          onSend={() => void submit()}
          sending={sending}
          value={draft}
          variant="message"
        />
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { backgroundColor: palette.background, flex: 1 },
  header: {
    alignItems: 'center',
    borderBottomColor: palette.border,
    borderBottomWidth: StyleSheet.hairlineWidth,
    flexDirection: 'row',
    padding: spacing.lg,
  },
  headerBody: { flex: 1 },
  title: { ...typeScale.headline, color: palette.text },
  subtitle: { ...typeScale.footnote, color: palette.textMuted },
  settings: { ...typeScale.footnote, color: palette.primary, fontWeight: '600' },
  list: { flex: 1, padding: spacing.lg },
  bubbleRow: { flexDirection: 'row', gap: spacing.sm, marginBottom: spacing.md },
  bubbleColumn: { flex: 1 },
  messageActions: { flexDirection: 'row', gap: spacing.md, marginTop: 2 },
  action: { ...typeScale.caption, color: palette.primary, fontWeight: '600' },
  receipt: { ...typeScale.caption, color: palette.textMuted },
  composerShell: {
    borderTopColor: palette.border,
    borderTopWidth: StyleSheet.hairlineWidth,
    padding: spacing.sm,
  },
  replyBar: {
    alignItems: 'center',
    backgroundColor: palette.surface,
    flexDirection: 'row',
    gap: spacing.sm,
    padding: spacing.sm,
  },
  replyText: { ...typeScale.footnote, color: palette.textMuted, flex: 1 },
  error: { ...typeScale.footnote, color: palette.danger, padding: spacing.sm },
  empty: { ...typeScale.body, color: palette.textMuted, padding: spacing.xl },
});
