import { useCallback, useState } from 'react';
import { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';
import { useSnapbackMutation } from '@expo/snapback-react';

import { palette, radii, spacing, typeScale } from '../../../src/social-ui';
import { AssetAvatar } from '../../../src/media';
import api, { useChatDetails, usePeopleSearch } from '../../../src/data';

export default function ChatSettingsScreen() {
  const { conversationId } = useLocalSearchParams<{ conversationId: string }>();
  const id = String(conversationId ?? '');
  const router = useRouter();
  const { details } = useChatDetails(id);
  const removeMember = useSnapbackMutation(api.removeMember);
  const addMember = useSnapbackMutation(api.addMember);
  const promoteMember = useSnapbackMutation(api.promoteMember);
  const [query, setQuery] = useState('');
  const { people } = usePeopleSearch(query);
  const [error, setError] = useState<string | null>(null);

  const run = useCallback(async (action: () => Promise<unknown>) => {
    setError(null);
    try {
      await action();
    } catch (caught) {
      const diagnostic = (caught as { diagnostic?: { details?: { appCode?: string } } }).diagnostic;
      const appCode = diagnostic?.details?.appCode;
      setError(
        appCode === 'NOT_ADMIN'
          ? 'Only an admin can change members.'
          : (caught instanceof Error ? caught.message : String(caught)),
      );
    }
  }, []);

  if (!details) {
    return (
      <View style={styles.screen}>
        <Text style={styles.empty}>This conversation is unavailable.</Text>
      </View>
    );
  }

  const memberIds = new Set(details.members.map((member) => member.profileId));

  return (
    <ScrollView style={styles.screen} testID="sm-chatsettings">
      <View style={styles.header}>
        <Pressable accessibilityRole="button" onPress={() => router.push(`/chat/${id}`)}>
          <Text style={styles.back}>‹ Back</Text>
        </Pressable>
        <Text style={styles.title}>Chat settings</Text>
      </View>
      <Text style={styles.label}>NAME</Text>
      <Text style={styles.value} testID="sm-chatsettings-name">{details.title}</Text>
      {details.kind === 'group' ? (
        <>
          <Text style={styles.label}>DESCRIPTION</Text>
          <Text style={styles.value} testID="sm-chatsettings-description">
            {details.description || '—'}
          </Text>
        </>
      ) : null}
      {error ? <Text style={styles.error} testID="sm-chatsettings-error">{error}</Text> : null}
      <Text style={styles.label}>{details.members.length} MEMBERS</Text>
      {details.members.map((member) => (
        <View key={member.profileId} style={styles.memberRow} testID="sm-chatsettings-member">
          <AssetAvatar assetId={member.avatarAssetId} label={member.displayName} size={32} />
          <View style={styles.memberBody}>
            <Text style={styles.memberName}>{member.displayName}</Text>
            <Text style={styles.memberMeta}>@{member.handle} · {member.role}</Text>
          </View>
          {details.kind === 'group' && member.role !== 'admin' ? (
            <Pressable
              accessibilityLabel={`Make ${member.displayName} an admin`}
              accessibilityRole="button"
              onPress={() => void run(() => promoteMember({
                conversationId: id, profileId: member.profileId,
              }))}
              testID="sm-chatsettings-member-promote"
            >
              <Text style={styles.action}>Make admin</Text>
            </Pressable>
          ) : null}
          {details.kind === 'group' ? (
            <Pressable
              accessibilityLabel={`Remove ${member.displayName}`}
              accessibilityRole="button"
              onPress={() => void run(() => removeMember({
                conversationId: id, profileId: member.profileId,
              }))}
              testID="sm-chatsettings-member-remove"
            >
              <Text style={styles.danger}>Remove</Text>
            </Pressable>
          ) : null}
        </View>
      ))}
      {details.kind === 'group' ? (
        <View style={styles.addBlock}>
          <Text style={styles.label}>ADD MEMBER</Text>
          <SearchInput onChange={setQuery} value={query} />
          {people.filter((person) => !memberIds.has(person.profileId)).slice(0, 8).map((person) => (
            <Pressable
              accessibilityRole="button"
              key={person.profileId}
              onPress={() => void run(() => addMember({
                conversationId: id, profileId: person.profileId,
              }))}
              style={styles.memberRow}
              testID="sm-chatsettings-member-add"
            >
              <AssetAvatar assetId={person.avatarAssetId} label={person.displayName} size={28} />
              <Text style={styles.memberName}>{person.displayName} @{person.handle}</Text>
            </Pressable>
          ))}
        </View>
      ) : null}
      <Pressable
        accessibilityRole="button"
        onPress={() => void run(async () => {
          await removeMember({ conversationId: id, profileId: details.viewerProfileId });
          router.push('/');
        })}
        style={styles.leave}
        testID="sm-chatsettings-leave"
      >
        <Text style={styles.danger}>Leave conversation</Text>
      </Pressable>
    </ScrollView>
  );
}

function SearchInput({ onChange, value }: { onChange: (text: string) => void; value: string }) {
  const { SearchBar } = require('../../../src/social-ui') as typeof import('../../../src/social-ui');
  return <SearchBar onChangeText={onChange} placeholder="Search people" value={value} />;
