import { useCallback, useMemo, useState } from 'react';
import { Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';
import { useRouter } from 'expo-router';
import { useSnapbackMutation } from '@expo/snapback-react';

import { SearchBar, palette, radii, spacing, typeScale } from '../src/social-ui';
import api, { usePeopleSearch } from '../src/data';

export default function NewChatScreen() {
  const router = useRouter();
  const [query, setQuery] = useState('');
  const { people } = usePeopleSearch(query);
  const createDm = useSnapbackMutation(api.createDm);
  const createGroup = useSnapbackMutation(api.createGroup);
  const [selected, setSelected] = useState<{ profileId: string; displayName: string }[]>([]);
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [error, setError] = useState<string | null>(null);

  const results = useMemo(() => people
    .filter((person) => !person.isSelf)
    .map((person) => ({
      id: person.profileId,
      title: person.displayName,
      subtitle: `@${person.handle}`,
    })), [people]);

  const toggle = useCallback((profileId: string) => {
    const person = people.find((candidate) => candidate.profileId === profileId);
    if (!person) return;
    setSelected((current) => (current.some((item) => item.profileId === profileId)
      ? current.filter((item) => item.profileId !== profileId)
      : [...current, { profileId, displayName: person.displayName }]));
  }, [people]);

  const startDm = useCallback(async () => {
    setError(null);
    if (selected.length !== 1) {
      setError('Pick exactly one person for a direct message.');
      return;
    }
    try {
      // Starting the "same" DM again resolves to the existing channel.
      const id = await createDm({ otherProfileId: selected[0].profileId });
      router.push(`/chat/${String(id)}`);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    }
  }, [createDm, router, selected]);

  const startGroup = useCallback(async () => {
    setError(null);
    if (title.trim().length === 0) {
      setError('A group needs a name.');
      return;
    }
    try {
      const id = await createGroup({
        title: title.trim(),
        description,
        memberProfileIds: selected.map((item) => item.profileId),
      });
      router.push(`/chat/${String(id)}`);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : String(caught));
    }
  }, [createGroup, description, router, selected, title]);

  return (
    <ScrollView style={styles.screen} testID="sm-new-chat">
      <Text style={styles.screenTitle}>New chat</Text>
      <SearchBar
        onChangeText={setQuery}
        onPressResult={toggle}
        placeholder="Search people"
        results={results}
        value={query}
      />
      <View style={styles.selected} testID="sm-new-chat-selected">
        {selected.map((person) => (
          <Pressable
            accessibilityRole="button"
            key={person.profileId}
            onPress={() => toggle(person.profileId)}
            style={styles.chip}
          >
            <Text style={styles.chipText}>{person.displayName} ✕</Text>
          </Pressable>
        ))}
        {selected.length === 0 ? <Text style={styles.hint}>No one selected yet</Text> : null}
      </View>
      {error ? <Text style={styles.error} testID="sm-new-chat-error">{error}</Text> : null}
      <Pressable
        accessibilityRole="button"
        onPress={() => void startDm()}
        style={styles.primary}
        testID="sm-new-chat-dm"
      >
        <Text style={styles.primaryText}>Start direct message</Text>
      </Pressable>
      <Text style={styles.label}>GROUP</Text>
      <TextInput
        accessibilityLabel="Group name"
        maxLength={50}
        onChangeText={setTitle}
        placeholder="Group name"
        placeholderTextColor={palette.textFaint}
        style={styles.input}
        testID="sm-new-group-title"
        value={title}
      />
      <TextInput
        accessibilityLabel="Group description"
        maxLength={200}
        onChangeText={setDescription}
        placeholder="Description (optional)"
        placeholderTextColor={palette.textFaint}
        style={styles.input}
        testID="sm-new-group-description"
        value={description}
      />
      <Pressable
        accessibilityRole="button"
        onPress={() => void startGroup()}
        style={styles.primary}
        testID="sm-new-group-submit"
      >
        <Text style={styles.primaryText}>Create group</Text>
      </Pressable>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  screen: { backgroundColor: palette.background, flex: 1 },
  screenTitle: {
    ...typeScale.title,
    color: palette.text,
    paddingHorizontal: spacing.lg,
    paddingTop: spacing.lg,
  },
  selected: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: spacing.sm,
    paddingHorizontal: spacing.lg,
    paddingVertical: spacing.sm,
  },
  chip: {
    backgroundColor: palette.surface,
    borderRadius: radii.pill,
    paddingHorizontal: spacing.md,
    paddingVertical: spacing.xs,
  },
  chipText: { ...typeScale.footnote, color: palette.text },
  hint: { ...typeScale.footnote, color: palette.textFaint },
  error: { ...typeScale.footnote, color: palette.danger, paddingHorizontal: spacing.lg },
  label: {
    ...typeScale.caption,
    color: palette.textMuted,
    fontWeight: '700',
    letterSpacing: 1,
    paddingHorizontal: spacing.lg,
    paddingTop: spacing.lg,
  },
  input: {
    ...typeScale.body,
    backgroundColor: palette.surface,
    borderRadius: radii.md,
    color: palette.text,
    marginHorizontal: spacing.lg,
    marginTop: spacing.sm,
    paddingHorizontal: spacing.md,
    paddingVertical: spacing.sm,
  },
  primary: {
    alignItems: 'center',
    backgroundColor: palette.primary,
    borderRadius: radii.md,
    margin: spacing.lg,
    paddingVertical: spacing.md,
  },
  primaryText: { ...typeScale.body, color: palette.textInverse, fontWeight: '700' },
});
