cat > tools/suite-lib.mjs <<'JSEOF'
// Shared helpers for the Clique acceptance suite.
import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';

import { FIXTURES, createPersonaClient, signInOrSignUp } from './replay.mjs';
import api, { app } from '../snapback/generated/api.mjs';

export const BASE_URL = process.env.CLIQUE_WEB ?? 'http://127.0.0.1:42161';
export const BACKEND = process.env.CLIQUE_BACKEND ?? 'http://127.0.0.1:42160';
export const UI_TIMEOUT = Number(process.env.CLIQUE_UI_TIMEOUT ?? 30_000);

export async function personas() {
  const text = await readFile(resolve(FIXTURES, 'personas.json'), 'utf8');
  const parsed = JSON.parse(text);
  const byId = new Map();
  for (const persona of parsed.starter) byId.set(persona.id, persona);
  return byId;
}

export function fixturePath(relative) {
  return resolve(FIXTURES, relative);
}

/** A headless application client signed in as one fixture persona. */
export async function headlessPersona(id, credential, label = id) {
  const { client } = createPersonaClient(BACKEND, app.identity.app, `${label}-${id}`);
  await signInOrSignUp(client, credential.email, credential.password);
  const mine = await client.query(api.myProfile, { args: {} });
  return {
    client,
    profileId: mine.rows.length > 0 ? mine.rows[0].profileId : null,
    async dispose() {
      try { await client.close(); } catch { /* best effort */ }
    },
  };
}

export async function signIn(context, credential) {
  const page = await context.newPage();
  await page.goto(BASE_URL, { waitUntil: 'domcontentloaded', timeout: UI_TIMEOUT });
  await page.getByTestId('sm-auth-email').fill(credential.email);
  await page.getByTestId('sm-auth-password').fill(credential.password);
  await page.getByTestId('sm-auth-submit').click();
  await page.getByTestId('sm-feed-tab-following').first()
    .waitFor({ state: 'visible', timeout: UI_TIMEOUT });
  return page;
}

export async function signUp(context, { email, password, displayName, handle }) {
  const page = await context.newPage();
  await page.goto(BASE_URL, { waitUntil: 'domcontentloaded', timeout: UI_TIMEOUT });
  await page.getByTestId('sm-auth-toggle').click();
  await page.getByTestId('sm-auth-displayname').fill(displayName);
  await page.getByTestId('sm-auth-handle').fill(handle);
  await page.getByTestId('sm-auth-email').fill(email);
  await page.getByTestId('sm-auth-password').fill(password);
  await page.getByTestId('sm-auth-submit').click();
  return page;
}

export async function openTab(page, tab) {
  await page.getByTestId(`sm-feed-tab-${tab}`).first().click();
  await page.getByTestId('sm-feed-scroll').waitFor({ state: 'visible', timeout: UI_TIMEOUT });
}

export async function feedEntryIds(page) {
  return page.evaluate(() => [...document.querySelectorAll('[data-testid="sm-feed-entry"]')]
    .map((element) => element.getAttribute('aria-label') ?? ''));
}

export async function feedTexts(page) {
  return page.evaluate(() => [...document.querySelectorAll('[data-testid="sm-feed-item"]')]
    .map((element) => element.textContent ?? ''));
}

export async function waitFor(predicate, { timeout = UI_TIMEOUT, description = 'condition' } = {}) {
  const started = Date.now();
  let last;
  while (Date.now() - started <= timeout) {
    last = await predicate();
    if (last) return last;
    await new Promise((done) => setTimeout(done, 120));
  }
  throw new Error(`${description} did not settle within ${timeout}ms`);
}

export async function composePost(page, text, files = null) {
  await openTab(page, 'global');
  if (files?.images?.length) {
    await page.getByTestId('sm-compose-file-images').setInputFiles(files.images);
  }
  if (files?.video) {
    await page.getByTestId('sm-compose-file-video').setInputFiles(files.video);
  }
  if (text.length > 0) await page.getByTestId('sm-compose-input').fill(text);
  await page.getByTestId('sm-compose-submit').click();
  if (text.length > 0) {
    await page.getByTestId('sm-feed-item').filter({ hasText: text }).first()
      .waitFor({ state: 'visible', timeout: UI_TIMEOUT });
  }
}

export { api };
JSEOF
