cat > tools/suite-m1.mjs <<'JSEOF'
// M1 — accounts and profiles. Suite-required assertions from the instrument's
// assertions.json: m1-a01, m1-a02, m1-a03, m1-a04, m1-a08, m1-a10, m1-a11.
import { UI_TIMEOUT, fixturePath, signIn, signUp, waitFor } from './suite-lib.mjs';

export const MILESTONE = 'M1';

export async function run(ctx) {
  const { browser, record, personas } = ctx;
  const stamp = Date.now().toString(36);
  const suiteUser = {
    email: `qa-${stamp}@example.com`,
    password: 'CliqueSuite!2026',
    displayName: `QA ${stamp}`,
    handle: `qa_${stamp}`.slice(0, 20),
  };
  ctx.state.suiteUser = suiteUser;
  const alice = personas.get('alice');

  const context = await browser.newContext();
  let page = null;

  await record('m1-a01', 'sign up with email + password (>= 8 chars) succeeds', async () => {
    page = await signUp(context, suiteUser);
    // Signup succeeded when the app leaves the auth screen for an
    // authenticated surface.
    await page.getByTestId('sm-feed-tab-following').first()
      .waitFor({ state: 'visible', timeout: UI_TIMEOUT });
    const authFields = await page.getByTestId('sm-auth-email').count();
    if (authFields !== 0) throw new Error('the auth form is still mounted after signup');
  });

  await record('m1-a02', 'after signup the app lands in the authenticated state', async () => {
    // The authenticated shell shows the viewer's own profile identity and the
    // signed-in surfaces; the sign-in form is unmounted.
    await page.getByTestId('sm-nav-me').waitFor({ state: 'visible', timeout: UI_TIMEOUT });
    const railText = await page.getByTestId('sm-nav-me').innerText();
    if (!railText.includes(suiteUser.displayName)) {
      throw new Error(`authenticated shell did not show ${suiteUser.displayName}: ${railText}`);
    }
    await page.goto(`${ctx.baseUrl}/profile/${suiteUser.handle}`, { waitUntil: 'domcontentloaded' });
    const profileText = await page.getByTestId('sm-profile').innerText();
    if (!profileText.includes(suiteUser.displayName)) {
      throw new Error('own profile did not render for the new account');
    }
  });

  await record('m1-a03', 'duplicate handle is rejected with a visible error', async () => {
    const duplicateContext = await browser.newContext();
    try {
      const duplicatePage = await signUp(duplicateContext, {
        email: `qa-dup-handle-${stamp}@example.com`,
        password: 'CliqueSuite!2026',
        displayName: 'Duplicate Handle',
        handle: alice.profile.handle,
      });
      const error = duplicatePage.getByTestId('sm-auth-error');
      await error.waitFor({ state: 'visible', timeout: UI_TIMEOUT });
      const text = (await error.innerText()).trim();
      if (text.length === 0) throw new Error('the duplicate-handle error was empty');
      const stillOnAuth = await duplicatePage.getByTestId('sm-auth-submit').count();
      if (stillOnAuth === 0) throw new Error('signup proceeded despite the duplicate handle');
      return { error: text };
    } finally {
      await duplicateContext.close();
    }
  });

  await record('m1-a04', 'duplicate email is rejected with a visible error', async () => {
    const duplicateContext = await browser.newContext();
    try {
      const duplicatePage = await signUp(duplicateContext, {
        email: alice.email,
        password: 'CliqueSuite!2026',
        displayName: 'Duplicate Email',
        handle: `qa_dupe_${stamp}`.slice(0, 20),
      });
      const error = duplicatePage.getByTestId('sm-auth-error');
      await error.waitFor({ state: 'visible', timeout: UI_TIMEOUT });
      const text = (await error.innerText()).trim();
      if (text.length === 0) throw new Error('the duplicate-email error was empty');
      const stillOnAuth = await duplicatePage.getByTestId('sm-auth-submit').count();
      if (stillOnAuth === 0) throw new Error('signup proceeded despite the duplicate email');
      return { error: text };
    } finally {
      await duplicateContext.close();
    }
  });

  await record('m1-a08', 'editing display name and bio persists', async () => {
    const nextName = `QA Edited ${stamp}`;
    const nextBio = `Bio edited by the acceptance suite ${stamp}.`;
    await page.goto(`${ctx.baseUrl}/profile/edit`, { waitUntil: 'domcontentloaded' });
