    await page.goto(`${ctx.baseUrl}/profile/${suiteUser.handle}`, { waitUntil: 'domcontentloaded' });
    await page.reload({ waitUntil: 'domcontentloaded' });
    const rendered = await waitFor(async () => page.evaluate(() => {
      const node = document.querySelector('[data-testid="sm-profile"] img');
      if (!node || !node.complete || node.naturalWidth === 0) return null;
      return { src: node.getAttribute('src'), width: node.naturalWidth };
    }), { description: 'avatar bytes on the profile' });
    return rendered;
  });

  await context.close();
