#!/usr/bin/env node
// Clique acceptance suite.
//
// One entrypoint per milestone:  npm run acceptance -- --milestone m1
//
// It installs the milestone's fixture action-log segments through the app's own
// write path, executes the milestone's suite-required assertions from the
// instrument's assertions.json against the running web client and backend,
// validates a coverage manifest (every suite-required assertion maps to a test),
// and writes the suite receipt, the suite-status linkage the choreography
// harness requires, and the typed D0.6 observation sidecar.

import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { performance } from 'node:perf_hooks';

import { chromium } from 'playwright';

import { ObservationWriter } from
  '/Users/ccheever/bench-matrix-20260823-r2/instrument/tools/social-messenger/metering/observations.mjs';

import { BASE_URL, personas } from './suite-lib.mjs';
import { FIXTURES, replayLogs } from './replay.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const APP_ROOT = resolve(HERE, '..');
const LANE_ROOT = resolve(APP_ROOT, '..');
const ASSERTIONS_PATH =
  '/Users/ccheever/bench-matrix-20260823-r2/instrument/schema/social-messenger/assertions.json';

const SEGMENTS = {
  m1: ['starter-m1.log'],
  m2: ['starter-m1.log', 'starter-m2.log'],
  m3: ['starter-m1.log', 'starter-m2.log', 'starter-m3.log'],
};

function parseArgs(argv) {
  const options = { milestone: null };
  for (let index = 0; index < argv.length; index += 1) {
    if (argv[index] === '--milestone') {
      index += 1;
      options.milestone = String(argv[index] ?? '').toLowerCase();
    } else if (argv[index].startsWith('--milestone=')) {
      options.milestone = argv[index].split('=')[1].toLowerCase();
    }
  }
  return options;
}

async function suiteRequiredIds(milestone) {
  const manifest = JSON.parse(await readFile(ASSERTIONS_PATH, 'utf8'));
  const key = milestone.toUpperCase();
  const entry = manifest.milestones[key];
  if (!entry) throw new Error(`assertions.json has no ${key}`);
  return entry.assertions
    .filter((assertion) => assertion.executor === 'suite-required')
    .map((assertion) => ({ id: assertion.id, text: assertion.text }));
}

async function main() {
  const options = parseArgs(process.argv.slice(2));
  const milestone = options.milestone;
  if (!SEGMENTS[milestone]) {
    process.stderr.write('usage: npm run acceptance -- --milestone m1|m2|m3\n');
    process.exitCode = 2;
    return;
  }
  const upper = milestone.toUpperCase();
  const laneRunId = process.env.CLIQUE_LANE_RUN_ID ?? 'opus-clique-explicit';
  const receiptsDir = resolve(LANE_ROOT, 'receipts');
  await mkdir(receiptsDir, { recursive: true });

  const observations = new ObservationWriter({
    path: resolve(receiptsDir, `${milestone}-suite.observations.jsonl`),
    laneRunId,
  });
  await observations.initialize();
  await observations.claim(upper, 'browserAssertionWait', { owner: 'suite' });
  await observations.claim(upper, 'restartReseed');

  const results = [];
  const started = performance.now();
  const startedAt = new Date().toISOString();

  // --- seed: replay this milestone's starter segments through the app's own
  // auth and mutation paths, then prove the replay is idempotent.
  const segmentPaths = SEGMENTS[milestone].map((name) => resolve(FIXTURES, name));
  await observations.reseed(upper, { destructive: false });
  const firstPass = await replayLogs(process.env.CLIQUE_BACKEND ?? 'http://127.0.0.1:42160', segmentPaths);
  await firstPass.replay.dispose();
  await observations.reseed(upper, { destructive: false });
  const secondPass = await replayLogs(process.env.CLIQUE_BACKEND ?? 'http://127.0.0.1:42160', segmentPaths);
  await secondPass.replay.dispose();

  const browser = await chromium.launch();
  const personaMap = await personas();
  const context = {
    browser,
    baseUrl: BASE_URL,
    personas: personaMap,
    milestone: upper,
    state: {
      seedFirstPass: firstPass.stats,
      seedSecondPass: secondPass.stats,
      segments: SEGMENTS[milestone],
    },
    async record(id, name, fn) {
      const attemptStart = performance.now();
      let pass = false;
      let detail = null;
      let error = null;
      try {
        detail = (await fn()) ?? null;
        pass = true;
      } catch (caught) {
        error = caught instanceof Error ? `${caught.message}` : String(caught);
      }
      const durationMs = Math.round((performance.now() - attemptStart) * 10) / 10;
      results.push({ id, name, pass, durationMs, detail, error });
      await observations.assertionWait(upper, {
        owner: 'suite',
        assertion: id,
        attempt: 1,
        durationMs,
        pass,
      });
      process.stdout.write(`${pass ? 'PASS' : 'FAIL'} ${id} ${name}${pass ? '' : ` :: ${error}`}\n`);
    },
  };

  try {
    const module = await import(`./suite-${milestone}.mjs`);
    await module.run(context);
  } catch (caught) {
    results.push({
      id: `${milestone}-suite-harness`,
      name: 'suite harness completed',
      pass: false,
      durationMs: 0,
      detail: null,
      error: caught instanceof Error ? caught.stack ?? caught.message : String(caught),
    });
    process.stdout.write(`FAIL suite harness :: ${caught}\n`);
  } finally {
    await browser.close();
  }

  // --- coverage manifest: every suite-required assertion maps to one test.
  const required = await suiteRequiredIds(milestone);
  const covered = new Set(results.map((result) => result.id));
  const missing = required.filter((assertion) => !covered.has(assertion.id));
  const coverage = required.map((assertion) => ({
    assertion: assertion.id,
    text: assertion.text,
    test: results.find((result) => result.id === assertion.id)?.name ?? null,
    covered: covered.has(assertion.id),
  }));

  const failed = results.filter((result) => !result.pass);
  const pass = failed.length === 0 && missing.length === 0;
  const receipt = {
    schemaVersion: 'clique.acceptance.v1',
    app: 'clique',
    laneRunId,
    milestone: upper,
    startedAt,
    finishedAt: new Date().toISOString(),
    durationMs: Math.round(performance.now() - started),
    baseUrl: BASE_URL,
    segments: SEGMENTS[milestone],
    seed: {
      firstPass: firstPass.stats,
      secondPass: secondPass.stats,
    },
    coverage: {
      suiteRequired: required.length,
      covered: coverage.filter((entry) => entry.covered).length,
      missing: missing.map((assertion) => assertion.id),
      map: coverage,
    },
    assertions: results,
    pass,
  };

  const receiptRelative = `receipts/${milestone}-suite.json`;
  await writeFile(resolve(LANE_ROOT, receiptRelative), `${JSON.stringify(receipt, null, 2)}\n`);

  // The choreography harness reads this linkage before it starts a browser.
  const statusPath = resolve(LANE_ROOT, 'suite-status.json');
  let status = {};
  try {
    status = JSON.parse(await readFile(statusPath, 'utf8'));
  } catch { /* first run */ }
  status[milestone] = { pass, receipt: receiptRelative };
  await writeFile(statusPath, `${JSON.stringify(status, null, 2)}\n`);

  process.stdout.write(
    `\n${upper}: ${results.filter((r) => r.pass).length}/${results.length} assertions passed; `
    + `coverage ${coverage.filter((e) => e.covered).length}/${required.length}`
    + `${missing.length > 0 ? ` (missing ${missing.map((m) => m.id).join(', ')})` : ''}\n`
    + `suite receipt: ${receiptRelative}\n`,
  );
  process.exitCode = pass ? 0 : 1;
}

await main();
