python3 - <<'PY'
p='src/feed.tsx'
s=open(p).read()
start = s.index("/**\n * One keyset page of the feed.")
end = s.index("export function LoadMoreButton(")
new_block = '''/**
 * The feed is a fixed set of keyset page slots. Page 0 is live and unbounded
 * above; each later slot pins an inclusive `beforeSortAt` cursor captured from
 * the last rendered row, so a concurrent insert can shift the window without
 * opening a gap, and the merge de-duplicates by `entryId`. Unused slots are
 * `skip`, which keeps the hook order fixed without a child-to-parent state
 * round trip.
 */
export const MAX_PAGES = 6;

function pageArgs(scope: 'following' | 'global', cursors: (number | null)[], index: number) {
  if (index >= cursors.length) return skip;
  const cursor = cursors[index];
  return cursor === null
    ? { scope, limit: PAGE_SIZE }
    : { scope, limit: PAGE_SIZE + 1, beforeSortAt: cursor };
}

function pageRows(state: { status: string; data?: unknown }): readonly FeedRow[] | null {
  if (state.status === 'ready' || state.status === 'refreshing') {
    return (state.data ?? []) as readonly FeedRow[];
  }
  return null;
}

export function useFeed(scope: 'following' | 'global') {
  const [cursors, setCursors] = useState<(number | null)[]>([null]);
  useEffect(() => { setCursors([null]); }, [scope]);

  const args = useMemo(
    () => Array.from({ length: MAX_PAGES }, (_, index) => pageArgs(scope, cursors, index)),
    [cursors, scope],
  );
  const states = [
    useSnapbackQuery(api.feedPage, args[0] as never),
    useSnapbackQuery(api.feedPage, args[1] as never),
    useSnapbackQuery(api.feedPage, args[2] as never),
    useSnapbackQuery(api.feedPage, args[3] as never),
    useSnapbackQuery(api.feedPage, args[4] as never),
    useSnapbackQuery(api.feedPage, args[5] as never),
  ];

  const pages = states.map(pageRows);
  const loadedCount = pages.filter((rows) => rows !== null).length;

  const merged = useMemo(() => {
    const seen = new Set<string>();
    const out: FeedRow[] = [];
    for (const rows of pages) {
      for (const row of rows ?? []) {
        if (seen.has(row.entryId)) continue;
        seen.add(row.entryId);
        out.push(row);
      }
    }
    out.sort((left, right) => right.sortAt - left.sortAt);
    return out;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pages.map((rows) => (rows ?? []).map((row) => row.entryId).join(',')).join('|')]);

  const lastIndex = cursors.length - 1;
  const lastRows = pages[lastIndex] ?? [];
  const canLoadMore = cursors.length < MAX_PAGES
    && lastRows.length >= (lastIndex === 0 ? PAGE_SIZE : PAGE_SIZE + 1);

  const loadMore = useCallback(() => {
    if (merged.length === 0) return;
    const nextCursor = merged[merged.length - 1].sortAt;
    setCursors((existing) => {
      if (existing.length >= MAX_PAGES) return existing;
      if (existing[existing.length - 1] === nextCursor) return existing;
      return [...existing, nextCursor];
    });
  }, [merged]);

  const handleScroll = useCallback((event: {
    nativeEvent: {
      contentOffset: { y: number };
      contentSize: { height: number };
      layoutMeasurement: { height: number };
    };
  }) => {
    const { contentOffset, contentSize, layoutMeasurement } = event.nativeEvent;
    if (contentOffset.y + layoutMeasurement.height >= contentSize.height - 240) loadMore();
  }, [loadMore]);

  return {
    rows: merged,
    canLoadMore,
    loadMore,
    handleScroll,
    loadedCount,
    pageCount: cursors.length,
    loaders: null,
  };
}

'''
s = s[:start] + new_block + s[end:]
s = s.replace("import { useCallback, useEffect, useMemo, useRef, useState } from 'react';",
              "import { useCallback, useEffect, useMemo, useState } from 'react';")
s = s.replace("import { useSnapbackQuery } from '@expo/snapback-react';",
              "import { skip, useSnapbackQuery } from '@expo/snapback-react';")
open(p,'w').write(s)
print('ok')
PY
