new_block = '''export const MAX_PAGES = 6;

const HEAD_FOLLOWING = Object.freeze({ scope: 'following', limit: PAGE_SIZE });
const HEAD_GLOBAL = Object.freeze({ scope: 'global', limit: PAGE_SIZE });

function pageArgs(scope: 'following' | 'global', cursors: (number | null)[], index: number) {
  if (index + 1 >= cursors.length) return skip;
  const cursor = cursors[index + 1];
  return { scope, limit: PAGE_SIZE + 1, beforeSortAt: cursor as number };
}

function pageRows(state: { status: string; data?: unknown }): readonly FeedRow[] | null {
  if (state.status === 'ready' || state.status === 'refreshing') {
    return (state.data ?? []) as readonly FeedRow[];
  }
  return null;
}

export function useFeed(scope: 'following' | 'global') {
  const [cursors, setCursors] = useState<(number | null)[]>([null]);
  useEffect(() => { setCursors([null]); }, [scope]);

  // Both tabs keep their first page live, so switching tabs renders from an
  // already-settled store instead of flashing empty while a new subscription
  // primes.
  const following = useSnapbackQuery(api.feedPage, HEAD_FOLLOWING as never);
  const global = useSnapbackQuery(api.feedPage, HEAD_GLOBAL as never);
  const head = scope === 'following' ? following : global;

  const extraArgs = useMemo(
    () => Array.from({ length: MAX_PAGES - 1 }, (_, index) => pageArgs(scope, cursors, index)),
    [cursors, scope],
  );
  const extras = [
    useSnapbackQuery(api.feedPage, extraArgs[0] as never),
    useSnapbackQuery(api.feedPage, extraArgs[1] as never),
    useSnapbackQuery(api.feedPage, extraArgs[2] as never),
    useSnapbackQuery(api.feedPage, extraArgs[3] as never),
    useSnapbackQuery(api.feedPage, extraArgs[4] as never),
  ];

  const states = [head, ...extras];
  const pages = states.map(pageRows);
  const loadedCount = pages.filter((rows) => rows !== null).length;
  const diagnostics = states
    .filter((state) => state.status !== 'skipped')
    .map((state) => `${state.status}/${state.freshness}/${state.connection}/${(state.data as unknown[] | undefined)?.length ?? 0}`)
    .join(' ');

  // Merged on each render across every loaded page slot: the page arrays are
  // bounded (at most MAX_PAGES x 21 rows) and memoizing on row identity would
  // hide live field updates, which are exactly what the feed must show.
  const seen = new Set<string>();
  const merged: FeedRow[] = [];
  for (const rows of pages) {
    for (const row of rows ?? []) {
      if (seen.has(row.entryId)) continue;
      seen.add(row.entryId);
      merged.push(row);
    }
  }
  merged.sort((left, right) => right.sortAt - left.sortAt);

  const lastIndex = cursors.length - 1;
  const lastRows = pages[lastIndex] ?? [];
  const canLoadMore = cursors.length < MAX_PAGES
    && lastRows.length >= (lastIndex === 0 ? PAGE_SIZE : PAGE_SIZE + 1);

  const loadMore = useCallback(() => {
    if (merged.length === 0) return;
    const nextCursor = merged[merged.length - 1].sortAt;
    setCursors((existing) => {
      if (existing.length >= MAX_PAGES) return existing;
      if (existing[existing.length - 1] === nextCursor) return existing;
      return [...existing, nextCursor];
    });
  }, [merged]);

  const handleScroll = useCallback((event: {
    nativeEvent: {
      contentOffset: { y: number };
      contentSize: { height: number };
      layoutMeasurement: { height: number };
    };
  }) => {
    const { contentOffset, contentSize, layoutMeasurement } = event.nativeEvent;
    if (contentOffset.y + layoutMeasurement.height >= contentSize.height - 240) loadMore();
  }, [loadMore]);

  return {
    rows: merged,
    canLoadMore,
    loadMore,
    handleScroll,
    loadedCount,
    diagnostics,
    pageCount: cursors.length,
  };
}

'''
