cd clique && cat > tools/suite-m2.mjs <<'JSEOF'
// M2 — posts and the follow graph. Suite-required assertions: m2-a01..a03,
// a06, a08..a13, a15..a18, a20..a27.
import {
  UI_TIMEOUT,
  api,
  feedEntryIds,
  feedTexts,
  fixturePath,
  headlessPersona,
  openTab,
  signIn,
  signUp,
  waitFor,
} from './suite-lib.mjs';
import { composePost } from './suite-lib.mjs';

export const MILESTONE = 'M2';

const LINK_POST_TEXT_PREFIX = 'Suite link post';

async function cardFor(page, text) {
  const card = page.getByTestId('sm-feed-item').filter({ hasText: text }).first();
  await card.waitFor({ state: 'visible', timeout: UI_TIMEOUT });
  return card;
}

async function tabHas(page, tab, text) {
  await openTab(page, tab);
  return waitFor(async () => {
    const texts = await feedTexts(page);
    return texts.some((value) => value.includes(text)) ? texts : null;
  }, { description: `${tab} feed contains ${text}` }).then(() => true).catch(() => false);
}

async function tabTexts(page, tab) {
  await openTab(page, tab);
  // Give the freshly selected tab a settled frame before reading it.
  await page.waitForTimeout(1_200);
  return feedTexts(page);
}

export async function run(ctx) {
  const { browser, record, personas } = ctx;
  const stamp = Date.now().toString(36);
  const alicePersona = personas.get('alice');
  const bobPersona = personas.get('bob');
  const carolPersona = personas.get('carol');

  const aliceContext = await browser.newContext();
  const bobContext = await browser.newContext();
  const alice = await signIn(aliceContext, alicePersona);
  const bob = await signIn(bobContext, bobPersona);

  const aliceApi = await headlessPersona('alice', alicePersona, 'm2');
  const bobApi = await headlessPersona('bob', bobPersona, 'm2');
  const carolApi = await headlessPersona('carol', carolPersona, 'm2');

  const textPost = `${stamp} suite text post`;
  const linkPost = `${LINK_POST_TEXT_PREFIX} ${stamp} https://example.com/cafe`;
  const imagePost = `${stamp} suite image post`;
  const videoPost = `${stamp} suite video post`;

  await record('m2-a01', 'create a text post', async () => {
    await composePost(alice, textPost);
    const card = await cardFor(alice, textPost);
    const text = await card.innerText();
    if (!text.includes(alicePersona.profile.displayName)) {
      throw new Error('the new post did not render its author');
    }
  });

  await record('m2-a02', 'create an image post with 2 fixture images', async () => {
    await composePost(alice, imagePost, {
      images: [fixturePath('media/img-02.png'), fixturePath('media/img-03.png')],
    });
    const entry = alice.getByTestId('sm-feed-entry').filter({ hasText: imagePost }).first();
    await entry.waitFor({ state: 'visible', timeout: UI_TIMEOUT });
    const images = entry.getByTestId('sm-feed-image');
    await waitFor(async () => (await images.count()) === 2, {
      description: 'two rendered post images',
    });
    const loaded = await entry.evaluate((node) => [...node.querySelectorAll('img')]
      .filter((image) => image.complete && image.naturalWidth > 0).length);
    if (loaded < 2) throw new Error(`only ${loaded} image(s) delivered bytes`);
    return { images: loaded };
  });

  await record('m2-a03', 'create a video post', async () => {
    await composePost(alice, videoPost, { video: fixturePath('media/vid-01.mp4') });
    const entry = alice.getByTestId('sm-feed-entry').filter({ hasText: videoPost }).first();
    await entry.waitFor({ state: 'visible', timeout: UI_TIMEOUT });
    await waitFor(
      async () => entry.evaluate((node) => {
        const video = node.querySelector('video');
        return !!video && video.readyState >= 1;
      }),
      { description: 'video post playable metadata' },
    );
    // A post never mixes images and video.
    const images = await entry.getByTestId('sm-feed-image').count();
    if (images !== 0) throw new Error('the video post also rendered images');
  });

  // --- follow graph -------------------------------------------------------
  await record('m2-a06', "Bob follows Alice; Alice's posts appear in Bob's Following feed", async () => {
    // Start from a known state: Bob does not follow Alice.
    await bobApi.client.mutate(api.setFollow, {
      args: {
        targetProfileId: aliceApi.profileId,
        following: false,
        mutationId: `suite-unfollow-${stamp}`,
      },
    });
    await bob.goto(`${ctx.baseUrl}/profile/alice`, { waitUntil: 'domcontentloaded' });
    await waitFor(
      async () => (await bob.getByTestId('sm-profile-follow').first().innerText()).trim() === 'Follow',
      { description: 'Bob shown as not following Alice' },
    );
    await bob.getByTestId('sm-profile-follow').first().click();
    await waitFor(
      async () => (await bob.getByTestId('sm-profile-follow').first().innerText()).trim() === 'Following',
      { description: 'follow toggle settles' },
    );
    const found = await tabHas(bob, 'following', textPost);
    if (!found) throw new Error("Alice's post is not in Bob's Following feed after the follow");
  });

  await record('m2-a08', "after unfollow, older Alice posts leave Bob's Following feed", async () => {
    // A post created before the follow ever existed proves "including older ones".
    const olderPost = 'Coffee time at the corner table';
    if (!await tabHas(bob, 'following', olderPost)) {
      throw new Error('the seeded older post was not projected while following');
    }
    await bob.goto(`${ctx.baseUrl}/profile/alice`, { waitUntil: 'domcontentloaded' });
    await bob.getByTestId('sm-profile-follow').first().click();
    await waitFor(
      async () => (await bob.getByTestId('sm-profile-follow').first().innerText()).trim() === 'Follow',
      { description: 'unfollow settles' },
    );
    const texts = await waitFor(async () => {
      const values = await tabTexts(bob, 'following');
      const gone = !values.some((value) => value.includes(olderPost))
        && !values.some((value) => value.includes(textPost));
      return gone ? values : null;
    }, { description: "Alice's posts gone from Bob's Following feed", timeout: 45_000 });
    return { followingEntries: texts.length };
  });

  await record('m2-a09', "after the unfollow Alice's posts remain in Bob's Global feed", async () => {
    const texts = await tabTexts(bob, 'global');
    for (const needle of [textPost, 'Coffee time at the corner table']) {
      if (!texts.some((value) => value.includes(needle))) {
        throw new Error(`Global feed lost ${JSON.stringify(needle)} after the unfollow`);
      }
    }
  });

  await record('m2-a10', "a post from an unfollowed user appears in Bob's Global feed", async () => {
    // Bob follows neither Alice (just unfollowed) nor Carol in the seed graph.
    const carolPost = `${stamp} carol unfollowed post`;
    await carolApi.client.mutate(api.createPost, { args: { text: carolPost, kind: 'text' } });
    ctx.state.carolPost = carolPost;
    const texts = await waitFor(async () => {
      const values = await tabTexts(bob, 'global');
      return values.some((value) => value.includes(carolPost)) ? values : null;
    }, { description: "Carol's post in Bob's Global feed" });
    return { entries: texts.length };
  });

  await record('m2-a11', "that same post is absent from Bob's Following feed", async () => {
    const carolPost = ctx.state.carolPost;
    const texts = await tabTexts(bob, 'following');
    if (texts.some((value) => value.includes(carolPost))) {
      throw new Error("an unfollowed author's post appeared in the Following feed");
    }
  });

  // --- links --------------------------------------------------------------
  await record('m2-a12', 'an http(s) URL in a post is tappable and opens the system browser', async () => {
