// M3 — messaging core. Suite-required assertions: m3-a03, m3-a04, m3-a05,
// m3-a10, m3-a11, m3-a14, m3-a15.
import { UI_TIMEOUT, api, headlessPersona, signIn, waitFor } from './suite-lib.mjs';

export const MILESTONE = 'M3';

function conversationIdFrom(url) {
  const match = /\/chat\/([^/?#]+)/u.exec(url);
  return match ? decodeURIComponent(match[1]) : null;
}

async function startDirectMessage(page, baseUrl, personName) {
  await page.goto(`${baseUrl}/new-chat`, { waitUntil: 'domcontentloaded' });
  await page.getByTestId('sm-search-input').fill(personName);
  const result = page.getByTestId('sm-search-result').filter({ hasText: personName }).first();
  await result.waitFor({ state: 'visible', timeout: UI_TIMEOUT });
  await result.click();
  await page.getByTestId('sm-new-chat-dm').click();
  await page.getByTestId('sm-convo-input').waitFor({ state: 'visible', timeout: UI_TIMEOUT });
  return conversationIdFrom(page.url());
}

async function createGroup(page, baseUrl, title, memberNames) {
  await page.goto(`${baseUrl}/new-chat`, { waitUntil: 'domcontentloaded' });
  for (const name of memberNames) {
    await page.getByTestId('sm-search-input').fill(name);
    const result = page.getByTestId('sm-search-result').filter({ hasText: name }).first();
    await result.waitFor({ state: 'visible', timeout: UI_TIMEOUT });
    await result.click();
    await waitFor(
      async () => (await page.getByTestId('sm-new-chat-selected').innerText()).includes(name),
      { description: `${name} selected` },
    );
  }
  await page.getByTestId('sm-new-group-title').fill(title);
  await page.getByTestId('sm-new-group-submit').click();
  await page.getByTestId('sm-convo-input').waitFor({ state: 'visible', timeout: UI_TIMEOUT });
  return conversationIdFrom(page.url());
}

async function sendMessage(page, text) {
  await waitFor(
    async () => (await page.getByTestId('sm-convo-input').inputValue()).length === 0,
    { description: 'message composer ready' },
  );
  await page.getByTestId('sm-convo-input').fill(text);
  await page.getByTestId('sm-convo-send').click();
  const bubble = page.getByTestId('sm-convo-bubble').filter({ hasText: text }).last();
  await bubble.waitFor({ state: 'visible', timeout: UI_TIMEOUT });
  return bubble;
}

export async function run(ctx) {
  const { browser, record, personas } = ctx;
  const stamp = Date.now().toString(36);
  const alicePersona = personas.get('alice');
  const bobPersona = personas.get('bob');
  const carolPersona = personas.get('carol');

  const aliceContext = await browser.newContext();
  const bobContext = await browser.newContext();
  const alice = await signIn(aliceContext, alicePersona);
  const bob = await signIn(bobContext, bobPersona);
  const aliceApi = await headlessPersona('alice', alicePersona, 'm3');
  const bobApi = await headlessPersona('bob', bobPersona, 'm3');
  const carolApi = await headlessPersona('carol', carolPersona, 'm3');

  await record('m3-a03', "starting the 'same' DM again reuses the existing channel", async () => {
    const first = await startDirectMessage(alice, ctx.baseUrl, bobPersona.profile.displayName);
    if (!first) throw new Error('the new DM did not open a conversation route');
    const second = await startDirectMessage(alice, ctx.baseUrl, bobPersona.profile.displayName);
    if (second !== first) {
      throw new Error(`starting the same DM created a second channel (${first} vs ${second})`);
    }
    // And the pair still has exactly one DM from either side.
    const mine = await aliceApi.client.query(api.myChats, { args: {} });
    const theirs = await bobApi.client.query(api.myChats, { args: {} });
    const dmCount = mine.rows.filter((row) => row.kind === 'dm'
      && row.title === bobPersona.profile.displayName).length;
    const otherCount = theirs.rows.filter((row) => row.kind === 'dm'
      && row.title === alicePersona.profile.displayName).length;
    if (dmCount !== 1 || otherCount !== 1) {
      throw new Error(`DM channels per pair: alice=${dmCount} bob=${otherCount}`);
    }
    ctx.state.dmId = first;
    return { conversationId: first };
  });

  const groupTitle = `Weekend crew ${stamp}`;

  await record('m3-a04', 'create a group with Alice, Bob and Carol', async () => {
    const id = await createGroup(alice, ctx.baseUrl, groupTitle, [
      bobPersona.profile.displayName,
      carolPersona.profile.displayName,
    ]);
    if (!id) throw new Error('group creation did not open a conversation route');
    ctx.state.groupOne = id;
    await alice.goto(`${ctx.baseUrl}/chat/${id}/settings`, { waitUntil: 'domcontentloaded' });
    const members = await waitFor(async () => {
      const rows = await alice.getByTestId('sm-chatsettings-member').allInnerTexts();
      return rows.length === 3 ? rows : null;
    }, { description: 'three group members' });
    const handles = members.map((row) => row.match(/@([a-z0-9_]+)/u)?.[1]).sort();
    if (handles.join(',') !== 'alice,bob,carol') {
      throw new Error(`group roster was ${handles.join(',')}`);
