    const original = `${stamp} original for the quote`;
    const reply = `${stamp} quoted reply body`;
    await alice.goto(`${ctx.baseUrl}/chat/${ctx.state.dmId}`, { waitUntil: 'domcontentloaded' });
    await alice.getByTestId('sm-convo-input').waitFor({ state: 'visible', timeout: UI_TIMEOUT });
    const originalBubble = await sendMessage(alice, original);
    await originalBubble.getByTestId('sm-convo-quote').click();
    await alice.getByTestId('sm-convo-reply-bar').waitFor({ state: 'visible', timeout: UI_TIMEOUT });
    const replyBubble = await sendMessage(alice, reply);
    const preview = replyBubble.getByTestId('sm-convo-quote-preview').first();
    await preview.waitFor({ state: 'visible', timeout: UI_TIMEOUT });
    const excerpt = await preview.innerText();
    if (!excerpt.includes(original)) {
      throw new Error(`the quoted excerpt did not carry the original: ${excerpt}`);
    }
    if (!excerpt.includes(alicePersona.profile.displayName)) {
      throw new Error('the quoted excerpt did not name the quoted sender');
    }
    ctx.state.quoted = { original, reply };
    return { excerpt: excerpt.slice(0, 90) };
  });

  await record('m3-a11', 'tapping the quoted excerpt jumps to the original message', async () => {
    const { original, reply } = ctx.state.quoted;
    // Push the original out of view first so "jump" is observable.
    for (let index = 0; index < 6; index += 1) {
      await sendMessage(alice, `${stamp} filler ${index}`);
    }
    const originalBubble = alice.getByTestId('sm-convo-bubble').filter({ hasText: original }).last();
    const before = await originalBubble.evaluate((node) => {
      const rect = node.getBoundingClientRect();
      return rect.top >= 0 && rect.bottom <= window.innerHeight;
    });
    const replyBubble = alice.getByTestId('sm-convo-bubble').filter({ hasText: reply }).last();
    await replyBubble.getByTestId('sm-convo-quote-preview').first().click();
    const inViewport = await waitFor(async () => originalBubble.evaluate((node) => {
      const rect = node.getBoundingClientRect();
      return rect.top >= 0 && rect.bottom <= window.innerHeight;
    }), { description: 'the original message scrolled into view' });
    return { visibleBeforeJump: before, visibleAfterJump: inViewport };
  });

  await record('m3-a14', 'a non-admin cannot remove members', async () => {
    const conversationId = ctx.state.groupOne;
    // Bob is an ordinary member of the group Alice created.
    await bob.goto(`${ctx.baseUrl}/chat/${conversationId}/settings`, { waitUntil: 'domcontentloaded' });
    const carolRow = bob.getByTestId('sm-chatsettings-member').filter({ hasText: '@carol' }).first();
    await carolRow.waitFor({ state: 'visible', timeout: UI_TIMEOUT });
    await carolRow.getByTestId('sm-chatsettings-member-remove').click();
    const error = await waitFor(async () => {
      const locator = bob.getByTestId('sm-chatsettings-error');
      if (await locator.count() === 0) return null;
      const text = (await locator.first().innerText()).trim();
      return text.length > 0 ? text : null;
    }, { description: 'a visible non-admin refusal' });
    // Carol is still a member, server-side.
    const details = await carolApi.client.query(api.chatDetails, { args: { conversationId } });
    const roster = details.rows[0]?.members.map((member) => member.handle).sort().join(',');
    if (roster !== 'alice,bob,carol') {
      throw new Error(`a non-admin changed the roster: ${roster}`);
    }
    // And the mutation itself refuses with the declared application code.
