      seedRefs: second.seedRefs,
      profiles: Object.keys(second.profiles).length,
      conversations: Object.keys(second.conversations).length,
    };
  });

  await aliceApi.dispose();
  await bobApi.dispose();
  await carolApi.dispose();
  await aliceContext.close();
  await bobContext.close();
}
