"""/**
 * Every user-initiated write uses the settled convenience, so the call resolves
 * with the generated result and a screen that needs the new entity's id (a DM,
 * a group) can navigate to it.
 *
 * One wrinkle: while the client is still establishing an authorization proof —
 * typically right after a route change or a reconnect — the non-queued dispatch
 * refuses before transport with one of the closed authority-fence codes below.
 * That refusal is effect-free by construction (it is raised in
 * `__beforeTransportDispatch`), so a bounded wait-and-retry is safe and is what
 * the diagnostic's own wording ("waits for authorization proof") describes.
 */
const AUTHORITY_UNSETTLED = new Set([
  'SNAPBACK_OUTBOX_AUTHORIZATION_SUSPENDED',
  'SNAPBACK_OUTBOX_AUTHORIZATION_STALE',
  'SNAPBACK_OUTBOX_AUTHORITY_GENERATION_STALE',
  'SNAPBACK_CLIENT_AUTHORITY_CLEARING',
  'SNAPBACK_CLIENT_AUTHORITY_STALE',
]);

function authorityUnsettled(error: unknown) {
  const value = error as { code?: string; diagnostic?: { code?: string } } | null;
  const code = value?.diagnostic?.code ?? value?.code ?? '';
  return AUTHORITY_UNSETTLED.has(code)
    || [...AUTHORITY_UNSETTLED].some((known) => String(
      (error as { message?: string })?.message ?? '',
    ).includes(known));
}

export function useAppMutation<Args, Result>(
  reference: Parameters<typeof useSnapbackSettledMutation>[0],
): (args: Args) => Promise<Result> {
  const dispatch = useSnapbackSettledMutation(reference as never);
  return useCallback(async (args: Args) => {
    let lastError: unknown = null;
    for (let attempt = 0; attempt < 12; attempt += 1) {
      try {
        return await (dispatch as unknown as (value: Args) => Promise<Result>)(args);
      } catch (error) {
        if (!authorityUnsettled(error)) throw error;
        lastError = error;
        await new Promise((done) => { setTimeout(done, 120); });
      }
    }
    throw lastError;
  }, [dispatch]);
}

